import React, { useState, useEffect, memo } from 'react';
import { GameState, Phase } from '../types';

interface TopPanelProps {
  state: GameState;
  onHomeClick: () => void;
}

// 优化：使用 memo 且只在 value 真正变化时才重新渲染
// 同时动画逻辑改为更轻量的 CSS 处理
const StatItem = memo(({ icon, label, value, delta, color, isWarning }: { icon: string, label: string, value: string | number, delta?: number, color: string, isWarning?: boolean }) => {
  const [isAnimating, setIsAnimating] = useState(false);

  useEffect(() => {
    // 只有当 delta 存在且不为0时，或者没有delta但value变化了，才做动画
    if (delta !== 0 || delta === undefined) {
      setIsAnimating(true);
      const timer = setTimeout(() => setIsAnimating(false), 500);
      return () => clearTimeout(timer);
    }
  }, [value, delta]);

  return (
    <div className={`flex flex-col items-center bg-white/20 backdrop-blur-md px-4 py-2 rounded-2xl border-b-4 transition-transform duration-300
      ${color} 
      ${isWarning ? 'animate-pulse border-red-500 bg-red-500/30' : ''} 
      ${isAnimating ? 'scale-110' : 'scale-100'}`}>
      <div className="flex items-center gap-2">
        <span className="text-2xl">{icon}</span>
        <span className={`text-white font-bold text-lg ${isWarning ? 'text-red-100' : ''}`}>{value}</span>
      </div>
      <div className="text-[10px] text-white/80 font-medium uppercase tracking-wider">
        {label} {delta !== undefined && (
          <span className={delta >= 0 ? 'text-green-300' : 'text-red-300'}>
            ({delta > 0 ? '+' : ''}{delta})
          </span>
        )}
      </div>
    </div>
  );
});

export const TopPanel: React.FC<TopPanelProps> = ({ state, onHomeClick }) => {
  const phaseNames = {
    [Phase.BUILD]: '建造阶段',
    [Phase.VOTE]: '投票阶段',
    [Phase.DISCUSS]: '讨论阶段'
  };

  const minutes = Math.floor(state.timer / 60);
  const seconds = state.timer % 60;

  const isPowerLow = state.power > state.powerCapacity;

  return (
    <div className="w-full h-20 bg-gradient-to-r from-blue-400 via-indigo-400 to-purple-400 flex items-center justify-between px-6 shadow-lg z-50">
      <div className="flex items-center gap-4">
        <button 
          onClick={onHomeClick} 
          className="mr-2 w-10 h-10 flex items-center justify-center bg-white/20 hover:bg-white/30 rounded-xl text-white transition-all active:scale-95 shadow-sm border border-white/20"
          title="返回首页"
        >
          <span className="text-xl">🏠</span>
        </button>
        <StatItem icon="💰" label="金币" value={state.gold.toLocaleString()} delta={state.goldDelta} color="border-yellow-400" />
        <StatItem icon="👥" label="人口" value={`${state.population}/${state.maxPopulation}`} color="border-blue-400" />
        <StatItem 
          icon="⚡" 
          label="电力" 
          value={`${Math.round(state.power)}/${Math.round(state.powerCapacity)}`} 
          color={isPowerLow ? "border-red-500" : "border-yellow-200"} 
          isWarning={isPowerLow}
        />
        <StatItem icon="🌳" label="污染" value={`${state.pollution}%`} color={state.pollution > 50 ? "border-red-500" : "border-green-400"} />
      </div>

      <div className="flex flex-col items-end">
        <div className="flex items-center gap-2 bg-black/30 px-4 py-1 rounded-full text-white">
          <span className="animate-pulse text-yellow-300">●</span>
          <span className="font-bold">{phaseNames[state.phase]}</span>
          <span className="border-l border-white/30 pl-2 ml-2">倒计时 {minutes}:{seconds.toString().padStart(2, '0')}</span>
        </div>
        <div className="text-white/70 text-sm mt-1">游戏内第 {state.day} 天</div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Task, Feedback, Role } from '../types';
import { ROLE_INFO } from '../constants';

interface SidebarRightProps {
  tasks: Task[];
  aiAdvice: string;
  feedbacks: Feedback[];
  onRewardClick: () => void;
  onSendFeedback?: (text: string) => void;
  currentRole: Role;
}

export const SidebarRight: React.FC<SidebarRightProps> = ({ tasks, aiAdvice, feedbacks, onRewardClick, onSendFeedback, currentRole }) => {
  const [inputText, setInputText] = useState('');

  const handleSend = () => {
    if (!inputText.trim()) return;
    onSendFeedback?.(inputText);
    setInputText('');
  };

  const roleInfo = ROLE_INFO[currentRole];

  return (
    <div className="w-80 h-full bg-white border-l border-gray-200 flex flex-col p-4 gap-4 overflow-hidden">
      {/* Tasks Section */}
      <section className="flex-1 min-h-0 bg-yellow-50 rounded-2xl p-4 border-2 border-yellow-200 flex flex-col overflow-hidden">
        <h3 className="text-yellow-800 font-bold mb-3 flex items-center gap-2 flex-shrink-0">
          <span>📋</span> 公共问题任务栏
        </h3>
        <ul className="space-y-2 text-sm overflow-y-auto pr-1">
          {tasks.map(task => (
            <li key={task.id} className="flex items-start gap-2 bg-white/50 p-2 rounded-lg border border-yellow-100 shadow-sm">
              <input type="checkbox" checked={task.completed} readOnly className="mt-1 accent-yellow-500" />
              <span className={`leading-tight ${task.completed ? 'line-through text-gray-400' : 'text-gray-700'} ${task.type === 'urgent' ? 'text-red-600 font-medium' : ''}`}>
                {task.title}
              </span>
            </li>
          ))}
        </ul>
      </section>

      {/* AI Advisor Section */}
      <section className="flex-1 min-h-0 bg-blue-50 rounded-2xl p-4 border-2 border-blue-200 flex flex-col overflow-hidden">
        <h3 className="text-blue-800 font-bold mb-3 flex items-center gap-2 flex-shrink-0">
          <span>🤖</span> 人工智能顾问分析
        </h3>
        <div className="flex-1 overflow-y-auto pr-1 mb-3">
          <div className="bg-white/80 p-4 rounded-xl italic text-gray-700 text-sm border border-blue-100 shadow-sm leading-relaxed">
            "{aiAdvice}"
          </div>
        </div>
        <button 
          onClick={onRewardClick}
          className="w-full bg-yellow-400 hover:bg-yellow-500 text-yellow-900 font-bold py-2 rounded-full transition-all active:scale-95 shadow-md flex-shrink-0"
        >
          获得奖励
        </button>
      </section>

      {/* Citizen Feedback Section */}
      <section className="flex-1 min-h-0 bg-pink-50 rounded-2xl p-4 border-2 border-pink-200 flex flex-col overflow-hidden">
        <h3 className="text-pink-800 font-bold mb-3 flex items-center gap-2 flex-shrink-0">
          <span>💬</span> 观点 (discuss)
        </h3>
        <div className="flex-1 overflow-y-auto space-y-3 pr-1 mb-3">
          {feedbacks.map(f => (
            <div key={f.id} className="flex gap-2 group">
              <img src={f.avatar} alt="avatar" className="w-8 h-8 rounded-full border-2 border-white shadow-sm flex-shrink-0 bg-gray-100" />
              <div className="flex-1">
                <div className="flex justify-between items-center mb-0.5">
                  <span className="text-[9px] font-bold text-gray-400 uppercase">{f.author}</span>
                  <span className="text-[8px] text-gray-300">{f.time}</span>
                </div>
                <div className="bg-white p-3 rounded-2xl rounded-tl-none shadow-sm text-xs text-gray-700 leading-relaxed border border-pink-100">
                  {f.text}
                </div>
              </div>
            </div>
          ))}
        </div>
        <div className="mt-auto flex flex-col gap-1 flex-shrink-0">
          <div className="px-2 text-[10px] text-gray-400 flex items-center gap-1">
            <span>正在发言:</span>
            <span className={`font-bold px-1.5 py-0.5 rounded text-white flex items-center gap-1 ${roleInfo.color}`}>
              {roleInfo.icon} {roleInfo.name}
            </span>
          </div>
          <div className="flex gap-2">
            <input 
              type="text" 
              value={inputText}
              onChange={(e) => setInputText(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSend()}
              placeholder="发表您的观点..." 
              className="flex-1 text-xs border border-pink-100 rounded-full px-4 py-2 outline-none focus:ring-2 focus:ring-pink-300 transition-all shadow-sm" 
            />
            <button 
              onClick={handleSend}
              className="bg-pink-500 hover:bg-pink-600 text-white w-9 h-9 flex items-center justify-center rounded-full text-xs shadow-md transition-all active:scale-90"
            >
              ➤
            </button>
          </div>
        </div>
      </section>
    </div>
  );
};

import React, { useState, useEffect, useCallback, useRef, useMemo } from 'react';
import { GameState, Phase, Role, Task, Feedback, MapCell, LogEvent, ViewState, VoteData } from './types';
import { INITIAL_STATE, BUILDINGS, GRID_SIZE, ROLE_INFO } from './constants';
import { TopPanel } from './components/TopPanel';
import { GameMap } from './components/Map';
import { SidebarLeft } from './components/SidebarLeft';
import { SidebarRight } from './components/SidebarRight';
import { BuildingInfoOverlay } from './components/BuildingInfoOverlay';
import { LogPage } from './components/LogPage';
import { VotePage } from './components/VotePage';
import { TutorialOverlay } from './components/TutorialOverlay';
import { ChildFeedbackPage } from './components/ChildFeedbackPage';
import { TeacherReportPage } from './components/TeacherReportPage';
import { getAIAdvice, generateFeedback, speakAdvice } from './services/geminiService';

const App: React.FC = () => {
  // 核心游戏状态：地图、日志、当前角色、当前阶段
  const [state, setState] = useState<GameState>(INITIAL_STATE);

  // 视图状态：游戏、日志、投票等
  const [view, setView] = useState<ViewState>('GAME');
  const [showTutorial, setShowTutorial] = useState(true);

  // 交互状态：选中建筑、选中的单元格
  const [selectedBuildingId, setSelectedBuildingId] = useState<string | null>(null);
  const [focusedCell, setFocusedCell] = useState<MapCell | null>(null);

  // 性能优化：通过 Ref 保持最新的 selectedBuildingId，确保点击回调永远稳定且不卡顿
  const selectedBuildingRef = useRef<string | null>(null);
  useEffect(() => { selectedBuildingRef.current = selectedBuildingId; }, [selectedBuildingId]);

  // 性能优化：通过 Ref 保持最新的 state，让事件处理函数可以访问最新状态而无需作为依赖重新创建
  const stateRef = useRef(state);
  useEffect(() => { stateRef.current = state; }, [state]);

  const lastCriticalAlertRef = useRef<number>(0);

  // 辅助状态：任务与反馈
  const [tasks, setTasks] = useState<Task[]>([
    { id: '1', title: '让所有住宅 4 格内至少有一所学校', completed: false, type: 'daily' },
    { id: '2', title: '城市总人口达到 500人', completed: false, type: 'urgent' },
    { id: '3', title: '污染指数降低至 20% 或以下 🌍', completed: false, type: 'daily' }
  ]);
  const [feedbacks, setFeedbacks] = useState<Feedback[]>([
    { id: '1', author: '市民A', text: '这边的电力供应看起来不太稳定', time: '16:04', avatar: 'https://picsum.photos/32/32?random=1' },
    { id: '2', author: '市民B', text: '我们需要更多绿化空间！', time: '16:30', avatar: 'https://picsum.photos/32/32?random=2' }
  ]);
  const [aiAdvice, setAiAdvice] = useState<string>("正在分析城市数据...");

  // 核心性能优化：计算城市运行数据（仅在地图或角色变动时执行）
  const cityStats = useMemo(() => {
    let goldDelta = 0;
    let powerUsed = 0;
    let powerCapacity = 0;
    let totalPollution = 20; // 基础污染
    let pop = 0;
    let targetHappiness = 0;

    state.map.flat().forEach(cell => {
      if (cell.buildingId || cell.isRoad) {
        const b = cell.buildingId ? BUILDINGS[cell.buildingId] : BUILDINGS['ROAD'];
        goldDelta += b.goldEffect;
        if (b.powerEffect > 0) powerCapacity += b.powerEffect;
        else powerUsed -= b.powerEffect;
        totalPollution += b.pollutionEffect;
        pop += b.popEffect;
        targetHappiness += b.happinessEffect;
      }
    });

    return { goldDelta, powerUsed, powerCapacity, totalPollution, pop, targetHappiness };
  }, [state.map]);

  // 处理副作用：语音警报
  useEffect(() => {
    const isCriticalPower = cityStats.powerUsed > cityStats.powerCapacity;
    const isCriticalPollution = cityStats.totalPollution > 50;

    if ((isCriticalPower || isCriticalPollution) && Date.now() - lastCriticalAlertRef.current > 45000) {
       lastCriticalAlertRef.current = Date.now();
       const msg = isCriticalPower ? "警告：城市电力不足，部分区域运转受限。" : "警告：污染水平过高，请立即增加绿化设施。";
       speakAdvice(msg);
    }
  }, [cityStats]);

  // 定期更新 AI 建议
  useEffect(() => {
    const fetchAdvice = async () => {
      const advice = await getAIAdvice(state);
      setAiAdvice(advice);
    };
    fetchAdvice();
  }, [state.phase, state.day]);

  // 游戏主计时器
  useEffect(() => {
    const timer = setInterval(() => {
      setState(prev => {
        const nextTimer = prev.timer > 0 ? prev.timer - 1 : 120;
        let nextPhase = prev.phase;
        let nextDay = prev.day;

        // 阶段切换逻辑
        if (prev.timer === 0) {
          if (prev.phase === Phase.BUILD) nextPhase = Phase.VOTE;
          else if (prev.phase === Phase.VOTE) nextPhase = Phase.DISCUSS;
          else {
            nextPhase = Phase.BUILD;
            nextDay += 1;
          }
        }

        // 金币每 10 秒结算一次
        const goldUpdate = prev.timer % 10 === 0 ? prev.goldDelta : 0;

        return {
          ...prev,
          timer: nextTimer,
          phase: nextPhase,
          day: nextDay,
          gold: prev.gold + goldUpdate,
          happiness: Math.min(100, Math.max(0, prev.happiness + (prev.happiness < 50 ? -1 : 1))) 
        };
      });
    }, 1000);

    return () => clearInterval(timer);
  }, []); 

  // 当 cityStats 变化时，同步到 State
  useEffect(() => {
    setState(prev => ({
      ...prev,
      goldDelta: cityStats.goldDelta,
      population: cityStats.pop,
      power: cityStats.powerUsed,
      powerCapacity: cityStats.powerCapacity,
      pollution: Math.max(0, Math.min(100, cityStats.totalPollution)),
    }));
  }, [cityStats]);

  // 处理任务自动完成逻辑
  useEffect(() => {
    setTasks(prev => prev.map(t => {
      // 任务1：让所有住宅 4 格内至少有一所学校
      if (t.id === '1') {
        const flatMap = state.map.flat();
        const residences = flatMap.filter(c => c.buildingId === 'RESIDENCE');
        const schools = flatMap.filter(c => c.buildingId === 'SCHOOL');

        // 只有当存在住宅时才开始检查
        if (residences.length > 0) {
          const allCovered = residences.every(r => {
            // 检查是否有任何一所学校在曼哈顿距离 <= 4 的范围内
            return schools.some(s => (Math.abs(r.x - s.x) + Math.abs(r.y - s.y)) <= 4);
          });
          if (allCovered) return { ...t, completed: true };
        }
      }

      // 任务2：人口达标
      if (t.id === '2' && state.population >= 500) return { ...t, completed: true };

      // 任务3：污染控制
      if (t.id === '3' && state.pollution <= 20) return { ...t, completed: true };

      return t;
    }));
  }, [state.population, state.pollution, state.map]); // 增加 state.map 依赖

  const handleCellClick = useCallback((x: number, y: number) => {
    const currentState = stateRef.current;
    const bId = selectedBuildingRef.current;
    const cell = currentState.map[y][x];

    if (cell.buildingId || cell.isRoad) {
      setFocusedCell(cell);
      return;
    }

    if (bId && !cell.buildingId && !cell.isRoad && currentState.phase === Phase.BUILD) {
      const building = BUILDINGS[bId];
      if (currentState.gold < building.cost) {
        alert("金币不足！");
        return;
      }

      setState(prev => {
        const currentCell = prev.map[y][x];
        if (currentCell.buildingId || currentCell.isRoad) return prev;

        const newMap = [...prev.map];
        newMap[y] = [...newMap[y]];
        newMap[y][x] = {
          ...newMap[y][x],
          buildingId: bId === 'ROAD' ? null : bId,
          isRoad: bId === 'ROAD',
          ownerId: prev.currentRole
        };

        const newLog: LogEvent = {
          session_id: prev.sessionId,
          timestamp: Math.floor((Date.now() - prev.startTime) / 1000),
          player_id: prev.currentRole,
          event_type: 'propose',
          building_type: bId,
          coordinates: [x, y],
          is_public: building.role === Role.PLANNER || building.role === Role.ENVIRONMENT,
        };

        return {
          ...prev,
          gold: prev.gold - building.cost,
          map: newMap,
          logs: [...prev.logs, newLog]
        };
      });
    }
  }, []);

  const handleDemolish = useCallback((x: number, y: number) => {
    setState(prev => {
      const newMap = [...prev.map];
      newMap[y] = [...newMap[y]];
      newMap[y][x] = { ...newMap[y][x], buildingId: null, isRoad: false, ownerId: null };

      return { ...prev, map: newMap };
    });
    setFocusedCell(null);
  }, []);

  const handleRestart = () => {
    if (!window.confirm("确定要重新开始吗？这将清空当前地图和资源。")) return;

    setState(prev => {
      const restartLog: LogEvent = {
        session_id: prev.sessionId,
        timestamp: Math.floor((Date.now() - prev.startTime) / 1000),
        player_id: prev.currentRole,
        event_type: 'propose',
        building_type: '重置游戏',
        coordinates: '全图',
        is_public: true,
      };

      const newMap = Array.from({ length: GRID_SIZE }, (_, y) =>
        Array.from({ length: GRID_SIZE }, (_, x) => ({
          x, y, buildingId: null, isRoad: false, status: 'normal', ownerId: null
        } as MapCell))
      );

      return {
        ...INITIAL_STATE,
        sessionId: prev.sessionId,
        startTime: prev.startTime,
        logs: [...prev.logs, restartLog],
        currentRole: prev.currentRole,
        map: newMap
      };
    });

    setSelectedBuildingId(null);
    setFocusedCell(null);
  };

  const handleHomeClick = () => {
    if (window.confirm("确定要返回首页并重置游戏吗？")) {
       window.location.reload();
    }
  };

  // 修复：实现发起投票逻辑
  const handleInitiateVote = (question: string, description: string) => {
    setState(prev => {
      const newVote: VoteData = {
        id: Date.now().toString(),
        question,
        description,
        options: [
          { id: 'plan_A', label: '赞成' },
          { id: 'plan_B', label: '反对' }
        ],
        results: {},
        reasons: {},
        status: 'active',
        initiator: prev.currentRole
      };

      const newLog: LogEvent = {
        session_id: prev.sessionId,
        timestamp: Math.floor((Date.now() - prev.startTime) / 1000),
        player_id: prev.currentRole,
        event_type: 'vote',
        discuss_tag: question,
        vote_option_id: 'INITIATED'
      };

      return {
        ...prev,
        currentVote: newVote,
        logs: [...prev.logs, newLog]
      };
    });
  };

  // 修复：实现提交投票逻辑
  const handleSubmitVote = (optionId: string, reason?: string) => {
    setState(prev => {
      if (!prev.currentVote) return prev;

      const updatedResults = { ...prev.currentVote.results, [prev.currentRole]: optionId };
      const updatedReasons = reason ? { ...prev.currentVote.reasons, [prev.currentRole]: reason } : prev.currentVote.reasons;

      const newLog: LogEvent = {
        session_id: prev.sessionId,
        timestamp: Math.floor((Date.now() - prev.startTime) / 1000),
        player_id: prev.currentRole,
        event_type: 'vote',
        vote_option_id: optionId
      };

      return {
        ...prev,
        currentVote: {
          ...prev.currentVote,
          results: updatedResults,
          reasons: updatedReasons
        },
        logs: [...prev.logs, newLog]
      };
    });
  };

  const handleSendFeedback = (text: string) => {
    const roleInfo = ROLE_INFO[state.currentRole];

    // 更新讨论界面显示
    setFeedbacks(prev => [{
      id: Date.now().toString(), 
      author: roleInfo.name, 
      text: text,
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      avatar: `https://api.dicebear.com/7.x/avataaars/svg?seed=${state.currentRole}`
    }, ...prev.slice(0, 15)]);

    // 记录到系统日志，用于报告分析
    setState(prev => ({
      ...prev,
      logs: [...prev.logs, {
        session_id: prev.sessionId,
        timestamp: Math.floor((Date.now() - prev.startTime) / 1000),
        player_id: prev.currentRole,
        event_type: 'discuss',
        discuss_tag: text
      }]
    }));
  };

  const switchRole = () => {
    setState(prev => {
      const roles = Object.values(Role);
      const nextIndex = (roles.indexOf(prev.currentRole) + 1) % roles.length;
      return { ...prev, currentRole: roles[nextIndex] };
    });
    setSelectedBuildingId(null);
    setFocusedCell(null);
  };

  const getAppBackground = () => {
    if (state.pollution > 60) return 'bg-stone-500';
    if (state.pollution > 40) return 'bg-stone-300';
    return 'bg-blue-50';
  };

  const memoizedTopPanel = useMemo(() => (
    <TopPanel state={state} onHomeClick={handleHomeClick} />
  ), [state.timer, state.gold, state.power, state.pollution, state.phase, state.day]);

  const memoizedSidebarLeft = useMemo(() => (
    <SidebarLeft 
      currentRole={state.currentRole} 
      onSelectBuilding={setSelectedBuildingId}
      selectedId={selectedBuildingId}
      gold={state.gold}
    />
  ), [state.currentRole, selectedBuildingId, state.gold]);

  const memoizedSidebarRight = useMemo(() => (
    <SidebarRight 
      tasks={tasks} aiAdvice={aiAdvice} feedbacks={feedbacks}
      currentRole={state.currentRole}
      onSendFeedback={handleSendFeedback}
      onRewardClick={() => { setState(prev => ({ ...prev, gold: prev.gold + 500 })); alert("获得政府奖励金！"); }}
    />
  ), [tasks, aiAdvice, feedbacks, state.currentRole]);

  return (
    <div className={`flex flex-col h-screen w-full transition-colors duration-[3000ms] select-none ${getAppBackground()}`}>
      {memoizedTopPanel}

      <div className={`smog-overlay ${state.pollution > 50 ? 'smog-active' : ''}`} style={{ opacity: state.pollution > 50 ? (state.pollution - 50) / 50 : 0 }}></div>

      {showTutorial && <TutorialOverlay onClose={() => setShowTutorial(false)} />}

      {view === 'LOGS' && <LogPage state={state} onBack={() => setView('GAME')} />}

      {/* 传递正确的投票处理函数 */}
      {view === 'VOTE' && (
        <VotePage 
          state={state} 
          onBack={() => setView('GAME')} 
          onSubmitVote={handleSubmitVote} 
          onInitiateVote={handleInitiateVote} 
        />
      )}

      {view === 'CHILD_FEEDBACK' && <ChildFeedbackPage state={state} onBack={() => setView('GAME')} />}
      {view === 'TEACHER_REPORT' && <TeacherReportPage state={state} onBack={() => setView('GAME')} />}

      <main className="flex flex-1 overflow-hidden">
        {memoizedSidebarLeft}

        <div className="flex-1 flex flex-col relative">
          <GameMap 
            map={state.map}
            isPowered={state.power <= state.powerCapacity}
            onCellClick={handleCellClick}
            selectedBuildingId={selectedBuildingId}
            focusedCell={focusedCell}
          />

          {focusedCell && (
            <BuildingInfoOverlay 
              cell={focusedCell} onClose={() => setFocusedCell(null)} onDemolish={handleDemolish}
            />
          )}

          <div className="absolute top-6 left-6 flex items-center gap-3 bg-white/95 p-3 rounded-2xl shadow-xl border border-gray-100 backdrop-blur-sm">
            <div className="bg-indigo-100 p-2 rounded-xl text-indigo-600">
               <span className="text-xl font-bold">#1</span>
            </div>
            <div>
              <span className="text-[10px] text-gray-400 block font-bold uppercase tracking-widest">当前活跃角色</span>
              <button onClick={switchRole} className="font-bold text-gray-800 hover:text-indigo-600 transition-colors flex items-center gap-1">
                 {state.currentRole} <span className="text-xs">🔄</span>
              </button>
            </div>
          </div>

          <div className="h-24 bg-white border-t border-gray-100 flex items-center justify-between px-10 shadow-2xl z-10">
            <div className="flex gap-4">
              <button onClick={() => setShowTutorial(true)} className="w-12 h-12 flex items-center justify-center bg-gray-100 hover:bg-gray-200 text-gray-400 rounded-2xl font-black text-xl transition-all">?</button>
              <button onClick={() => setSelectedBuildingId(null)} className={`px-8 py-3 rounded-2xl font-bold transition-all ${!selectedBuildingId && !focusedCell ? 'bg-indigo-500 text-white shadow-lg' : 'bg-gray-50 text-gray-400'}`}>选择模式</button>
              <button onClick={handleRestart} className="px-8 py-3 rounded-2xl font-bold transition-all bg-rose-100 text-rose-500 hover:bg-rose-200 shadow-sm">重新开始</button>
              <button className={`px-8 py-3 rounded-2xl font-bold transition-all ${selectedBuildingId ? 'bg-yellow-400 text-yellow-900 shadow-lg' : 'bg-gray-50 text-gray-400'}`}>建造模式</button>
            </div>

            <div className="flex gap-8 items-center">
              <button onClick={() => setView('VOTE')} className="group flex flex-col items-center gap-1">
                 <span className="text-2xl">🗳️</span>
                 <span className="text-[10px] font-bold text-gray-400 uppercase">投票</span>
              </button>
              <button onClick={() => setView('CHILD_FEEDBACK')} className="group flex flex-col items-center gap-1">
                 <span className="text-2xl">👤📝</span>
                 <span className="text-[10px] font-bold text-gray-400 uppercase">反馈</span>
              </button>
              <button onClick={() => setView('TEACHER_REPORT')} className="group flex flex-col items-center gap-1">
                 <span className="text-2xl">📊</span>
                 <span className="text-[10px] font-bold text-gray-400 uppercase">报告</span>
              </button>
              <button onClick={() => setView('LOGS')} className="group flex flex-col items-center gap-1">
                 <span className="text-2xl">📝</span>
                 <span className="text-[10px] font-bold text-gray-400 uppercase">日志</span>
              </button>
            </div>
          </div>
        </div>

        {memoizedSidebarRight}
      </main>
    </div>
  );
};

export default App;

export enum Role {
  ENVIRONMENT = 'ENVIRONMENT',
  PLANNER = 'PLANNER',
  ENERGY = 'ENERGY',
  ECONOMIST = 'ECONOMIST'
}

export enum Phase {
  BUILD = 'BUILD',
  VOTE = 'VOTE',
  DISCUSS = 'DISCUSS'
}

export type ViewState = 'GAME' | 'LOGS' | 'VOTE' | 'CHILD_FEEDBACK' | 'TEACHER_REPORT';

export interface VoteData {
  id: string;
  question: string;
  description: string;
  options: { id: string, label: string }[];
  results: Record<string, string>; // player_id -> option_id
  reasons: Record<string, string>; // player_id -> text
  status: 'active' | 'completed';
  initiator: Role;
}

export interface LogEvent {
  session_id: string;
  timestamp: number; // seconds from start
  player_id: string; // current role
  event_type: 'propose' | 'modify_own' | 'modify_other' | 'vote' | 'discuss' | 'solve';
  building_type?: string;
  coordinates?: [number, number] | string;
  is_public?: boolean | string;
  target_owner_id?: string;
  vote_option_id?: string;
  discuss_tag?: string;
  problem_id?: string;
  modification?: string;
}

export interface Building {
  id: string;
  name: string;
  emoji: string;
  role: Role;
  cost: number;
  goldEffect: number;
  powerEffect: number;
  popEffect: number;
  pollutionEffect: number;
  happinessEffect: number;
  description: string;
}

export interface MapCell {
  x: number;
  y: number;
  buildingId: string | null;
  isRoad: boolean;
  status: 'normal' | 'no-power' | 'no-road';
  ownerId: Role | null;
}

export interface GameState {
  gold: number;
  goldDelta: number;
  population: number;
  maxPopulation: number;
  power: number;
  powerCapacity: number;
  pollution: number;
  happiness: number;
  day: number;
  phase: Phase;
  timer: number;
  currentRole: Role;
  map: MapCell[][];
  logs: LogEvent[];
  startTime: number;
  sessionId: string;
  currentVote: VoteData | null;
}

export interface Task {
  id: string;
  title: string;
  completed: boolean;
  type: 'urgent' | 'daily';
  deadline?: number;
}

export interface Feedback {
  id: string;
  author: string;
  text: string;
  time: string;
  avatar: string;
}

import React, { useState, useEffect, useCallback, useRef, useMemo } from 'react';
import { GameState, Phase, Role, Task, Feedback, MapCell, LogEvent, ViewState, VoteData } from './types';
import { INITIAL_STATE, BUILDINGS, GRID_SIZE, ROLE_INFO } from './constants';
import { TopPanel } from './components/TopPanel';
import { GameMap } from './components/Map';
import { SidebarLeft } from './components/SidebarLeft';
import { SidebarRight } from './components/SidebarRight';
import { BuildingInfoOverlay } from './components/BuildingInfoOverlay';
import { LogPage } from './components/LogPage';
import { VotePage } from './components/VotePage';
import { TutorialOverlay } from './components/TutorialOverlay';
import { ChildFeedbackPage } from './components/ChildFeedbackPage';
import { TeacherReportPage } from './components/TeacherReportPage';
import { getAIAdvice, generateFeedback, speakAdvice } from './services/geminiService';

const App: React.FC = () => {
  // 核心游戏状态：地图、日志、当前角色、当前阶段
  const [state, setState] = useState<GameState>(INITIAL_STATE);

  // 视图状态：游戏、日志、投票等
  const [view, setView] = useState<ViewState>('GAME');
  const [showTutorial, setShowTutorial] = useState(true);

  // 交互状态：选中建筑、选中的单元格
  const [selectedBuildingId, setSelectedBuildingId] = useState<string | null>(null);
  const [focusedCell, setFocusedCell] = useState<MapCell | null>(null);

  // 性能优化：通过 Ref 保持最新的 selectedBuildingId，确保点击回调永远稳定且不卡顿
  const selectedBuildingRef = useRef<string | null>(null);
  useEffect(() => { selectedBuildingRef.current = selectedBuildingId; }, [selectedBuildingId]);

  // 性能优化：通过 Ref 保持最新的 state，让事件处理函数可以访问最新状态而无需作为依赖重新创建
  const stateRef = useRef(state);
  useEffect(() => { stateRef.current = state; }, [state]);

  const lastCriticalAlertRef = useRef<number>(0);

  // 辅助状态：任务与反馈
  const [tasks, setTasks] = useState<Task[]>([
    { id: '1', title: '让所有住宅 4 格内至少有一所学校', completed: false, type: 'daily' },
    { id: '2', title: '城市总人口达到 500人', completed: false, type: 'urgent' },
    { id: '3', title: '污染指数降低至 20% 或以下 🌍', completed: false, type: 'daily' }
  ]);
  const [feedbacks, setFeedbacks] = useState<Feedback[]>([
    { id: '1', author: '市民A', text: '这边的电力供应看起来不太稳定', time: '16:04', avatar: 'https://picsum.photos/32/32?random=1' },
    { id: '2', author: '市民B', text: '我们需要更多绿化空间！', time: '16:30', avatar: 'https://picsum.photos/32/32?random=2' }
  ]);
  const [aiAdvice, setAiAdvice] = useState<string>("正在分析城市数据...");

  // 核心性能优化：计算城市运行数据（仅在地图或角色变动时执行）
  const cityStats = useMemo(() => {
    let goldDelta = 0;
    let powerUsed = 0;
    let powerCapacity = 0;
    let totalPollution = 20; // 基础污染
    let pop = 0;
    let targetHappiness = 0;

    state.map.flat().forEach(cell => {
      if (cell.buildingId || cell.isRoad) {
        const b = cell.buildingId ? BUILDINGS[cell.buildingId] : BUILDINGS['ROAD'];
        goldDelta += b.goldEffect;
        if (b.powerEffect > 0) powerCapacity += b.powerEffect;
        else powerUsed -= b.powerEffect;
        totalPollution += b.pollutionEffect;
        pop += b.popEffect;
        targetHappiness += b.happinessEffect;
      }
    });

    return { goldDelta, powerUsed, powerCapacity, totalPollution, pop, targetHappiness };
  }, [state.map]);

  // 处理副作用：语音警报
  useEffect(() => {
    const isCriticalPower = cityStats.powerUsed > cityStats.powerCapacity;
    const isCriticalPollution = cityStats.totalPollution > 50;

    if ((isCriticalPower || isCriticalPollution) && Date.now() - lastCriticalAlertRef.current > 45000) {
       lastCriticalAlertRef.current = Date.now();
       const msg = isCriticalPower ? "警告：城市电力不足，部分区域运转受限。" : "警告：污染水平过高，请立即增加绿化设施。";
       speakAdvice(msg);
    }
  }, [cityStats]);

  // 定期更新 AI 建议
  useEffect(() => {
    const fetchAdvice = async () => {
      const advice = await getAIAdvice(state);
      setAiAdvice(advice);
    };
    fetchAdvice();
  }, [state.phase, state.day]);

  // 游戏主计时器
  useEffect(() => {
    const timer = setInterval(() => {
      setState(prev => {
        const nextTimer = prev.timer > 0 ? prev.timer - 1 : 120;
        let nextPhase = prev.phase;
        let nextDay = prev.day;

        // 阶段切换逻辑
        if (prev.timer === 0) {
          if (prev.phase === Phase.BUILD) nextPhase = Phase.VOTE;
          else if (prev.phase === Phase.VOTE) nextPhase = Phase.DISCUSS;
          else {
            nextPhase = Phase.BUILD;
            nextDay += 1;
          }
        }

        // 金币每 10 秒结算一次
        const goldUpdate = prev.timer % 10 === 0 ? prev.goldDelta : 0;

        return {
          ...prev,
          timer: nextTimer,
          phase: nextPhase,
          day: nextDay,
          gold: prev.gold + goldUpdate,
          happiness: Math.min(100, Math.max(0, prev.happiness + (prev.happiness < 50 ? -1 : 1))) 
        };
      });
    }, 1000);

    return () => clearInterval(timer);
  }, []); 

  // 当 cityStats 变化时，同步到 State
  useEffect(() => {
    setState(prev => ({
      ...prev,
      goldDelta: cityStats.goldDelta,
      population: cityStats.pop,
      power: cityStats.powerUsed,
      powerCapacity: cityStats.powerCapacity,
      pollution: Math.max(0, Math.min(100, cityStats.totalPollution)),
    }));
  }, [cityStats]);

  // 处理任务自动完成逻辑 & 记录 Log
  useEffect(() => {
    setTasks(prevTasks => {
      let hasChanges = false;
      const newTasks = prevTasks.map(t => {
        if (t.completed) return t;

        let completed = false;

        // 任务1：让所有住宅 4 格内至少有一所学校
        if (t.id === '1') {
          const flatMap = state.map.flat();
          const residences = flatMap.filter(c => c.buildingId === 'RESIDENCE');
          const schools = flatMap.filter(c => c.buildingId === 'SCHOOL');
          if (residences.length > 0) {
            completed = residences.every(r => schools.some(s => (Math.abs(r.x - s.x) + Math.abs(r.y - s.y)) <= 4));
          }
        }
        // 任务2：人口达标
        else if (t.id === '2' && state.population >= 500) {
          completed = true;
        }
        // 任务3：污染控制
        else if (t.id === '3' && state.pollution <= 20) {
          completed = true;
        }

        if (completed) {
          hasChanges = true;
          // Side-effect: Log the 'solve' event
          // Note: Avoid calling setState directly inside this map loop to prevent conflicts.
          // We will handle the log update separately via a setTimeout or by checking changes.
          return { ...t, completed: true };
        }
        return t;
      });

      if (hasChanges) {
        // 记录任务完成的 Log
        const newlyCompleted = newTasks.filter(nt => !prevTasks.find(pt => pt.id === nt.id)?.completed);
        newlyCompleted.forEach(task => {
           setState(current => ({
             ...current,
             logs: [...current.logs, {
               session_id: current.sessionId,
               timestamp: Math.floor((Date.now() - current.startTime) / 1000),
               player_id: current.currentRole,
               event_type: 'solve',
               problem_id: task.id,
               discuss_tag: `Completed: ${task.title}`
             }]
           }));
        });
      }

      return hasChanges ? newTasks : prevTasks;
    });
  }, [state.population, state.pollution, state.map]);

  const handleCellClick = useCallback((x: number, y: number) => {
    const currentState = stateRef.current;
    const bId = selectedBuildingRef.current;
    const cell = currentState.map[y][x];

    if (cell.buildingId || cell.isRoad) {
      setFocusedCell(cell);
      return;
    }

    if (bId && !cell.buildingId && !cell.isRoad && currentState.phase === Phase.BUILD) {
      const building = BUILDINGS[bId];
      if (currentState.gold < building.cost) {
        alert("金币不足！");
        return;
      }

      setState(prev => {
        const currentCell = prev.map[y][x];
        if (currentCell.buildingId || currentCell.isRoad) return prev;

        const newMap = [...prev.map];
        newMap[y] = [...newMap[y]];
        newMap[y][x] = {
          ...newMap[y][x],
          buildingId: bId === 'ROAD' ? null : bId,
          isRoad: bId === 'ROAD',
          ownerId: prev.currentRole
        };

        const newLog: LogEvent = {
          session_id: prev.sessionId,
          timestamp: Math.floor((Date.now() - prev.startTime) / 1000),
          player_id: prev.currentRole,
          event_type: 'propose',
          building_type: bId,
          coordinates: [x, y],
          is_public: building.role === Role.PLANNER || building.role === Role.ENVIRONMENT,
        };

        return {
          ...prev,
          gold: prev.gold - building.cost,
          map: newMap,
          logs: [...prev.logs, newLog]
        };
      });
    }
  }, []);

  // 修复：记录 modify_own 和 modify_other
  const handleDemolish = useCallback((x: number, y: number) => {
    setState(prev => {
      const cell = prev.map[y][x];
      const newMap = [...prev.map];
      newMap[y] = [...newMap[y]];
      newMap[y][x] = { ...newMap[y][x], buildingId: null, isRoad: false, ownerId: null };

      // Determine modification type
      const isOwnBuilding = cell.ownerId === prev.currentRole;
      const eventType = isOwnBuilding ? 'modify_own' : 'modify_other';
      const buildingName = cell.buildingId ? BUILDINGS[cell.buildingId]?.name : 'Road';

      const newLog: LogEvent = {
        session_id: prev.sessionId,
        timestamp: Math.floor((Date.now() - prev.startTime) / 1000),
        player_id: prev.currentRole,
        event_type: eventType,
        building_type: cell.buildingId || 'ROAD',
        coordinates: [x, y],
        target_owner_id: cell.ownerId || 'SYSTEM',
        modification: `Demolished ${buildingName}`
      };

      return { ...prev, map: newMap, logs: [...prev.logs, newLog] };
    });
    setFocusedCell(null);
  }, []);

  const handleRestart = () => {
    if (!window.confirm("确定要重新开始吗？这将清空当前地图和资源。")) return;

    setState(prev => {
      const restartLog: LogEvent = {
        session_id: prev.sessionId,
        timestamp: Math.floor((Date.now() - prev.startTime) / 1000),
        player_id: prev.currentRole,
        event_type: 'propose',
        building_type: '重置游戏',
        coordinates: '全图',
        is_public: true,
      };

      const newMap = Array.from({ length: GRID_SIZE }, (_, y) =>
        Array.from({ length: GRID_SIZE }, (_, x) => ({
          x, y, buildingId: null, isRoad: false, status: 'normal', ownerId: null
        } as MapCell))
      );

      return {
        ...INITIAL_STATE,
        sessionId: prev.sessionId,
        startTime: prev.startTime,
        logs: [...prev.logs, restartLog],
        currentRole: prev.currentRole,
        map: newMap
      };
    });

    setSelectedBuildingId(null);
    setFocusedCell(null);
  };

  const handleHomeClick = () => {
    if (window.confirm("确定要返回首页并重置游戏吗？")) {
       window.location.reload();
    }
  };

  // 修复：实现发起投票逻辑
  const handleInitiateVote = (question: string, description: string) => {
    setState(prev => {
      const newVote: VoteData = {
        id: Date.now().toString(),
        question,
        description,
        options: [
          { id: 'plan_A', label: '赞成' },
          { id: 'plan_B', label: '反对' }
        ],
        results: {},
        reasons: {},
        status: 'active',
        initiator: prev.currentRole
      };

      const newLog: LogEvent = {
        session_id: prev.sessionId,
        timestamp: Math.floor((Date.now() - prev.startTime) / 1000),
        player_id: prev.currentRole,
        event_type: 'vote',
        discuss_tag: question,
        vote_option_id: 'INITIATED'
      };

      return {
        ...prev,
        currentVote: newVote,
        logs: [...prev.logs, newLog]
      };
    });
  };

  // 修复：实现提交投票逻辑
  const handleSubmitVote = (optionId: string, reason?: string) => {
    setState(prev => {
      if (!prev.currentVote) return prev;

      const updatedResults = { ...prev.currentVote.results, [prev.currentRole]: optionId };
      const updatedReasons = reason ? { ...prev.currentVote.reasons, [prev.currentRole]: reason } : prev.currentVote.reasons;

      const newLog: LogEvent = {
        session_id: prev.sessionId,
        timestamp: Math.floor((Date.now() - prev.startTime) / 1000),
        player_id: prev.currentRole,
        event_type: 'vote',
        vote_option_id: optionId
      };

      return {
        ...prev,
        currentVote: {
          ...prev.currentVote,
          results: updatedResults,
          reasons: updatedReasons
        },
        logs: [...prev.logs, newLog]
      };
    });
  };

  const handleSendFeedback = (text: string) => {
    const roleInfo = ROLE_INFO[state.currentRole];

    // 更新讨论界面显示
    setFeedbacks(prev => [{
      id: Date.now().toString(), 
      author: roleInfo.name, 
      text: text,
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      avatar: `https://api.dicebear.com/7.x/avataaars/svg?seed=${state.currentRole}`
    }, ...prev.slice(0, 15)]);

    // 记录到系统日志，用于报告分析 - 确保 event_type 是 'discuss'
    setState(prev => ({
      ...prev,
      logs: [...prev.logs, {
        session_id: prev.sessionId,
        timestamp: Math.floor((Date.now() - prev.startTime) / 1000),
        player_id: prev.currentRole,
        event_type: 'discuss',
        discuss_tag: text
      }]
    }));
  };

  const switchRole = () => {
    setState(prev => {
      const roles = Object.values(Role);
      const nextIndex = (roles.indexOf(prev.currentRole) + 1) % roles.length;
      return { ...prev, currentRole: roles[nextIndex] };
    });
    setSelectedBuildingId(null);
    setFocusedCell(null);
  };

  const getAppBackground = () => {
    if (state.pollution > 60) return 'bg-stone-500';
    if (state.pollution > 40) return 'bg-stone-300';
    return 'bg-blue-50';
  };

  const memoizedTopPanel = useMemo(() => (
    <TopPanel state={state} onHomeClick={handleHomeClick} />
  ), [state.timer, state.gold, state.power, state.pollution, state.phase, state.day]);

  const memoizedSidebarLeft = useMemo(() => (
    <SidebarLeft 
      currentRole={state.currentRole} 
      onSelectBuilding={setSelectedBuildingId}
      selectedId={selectedBuildingId}
      gold={state.gold}
    />
  ), [state.currentRole, selectedBuildingId, state.gold]);

  const memoizedSidebarRight = useMemo(() => (
    <SidebarRight 
      tasks={tasks} aiAdvice={aiAdvice} feedbacks={feedbacks}
      currentRole={state.currentRole}
      onSendFeedback={handleSendFeedback}
      onRewardClick={() => { setState(prev => ({ ...prev, gold: prev.gold + 500 })); alert("获得政府奖励金！"); }}
    />
  ), [tasks, aiAdvice, feedbacks, state.currentRole]);

  return (
    <div className={`flex flex-col h-screen w-full transition-colors duration-[3000ms] select-none ${getAppBackground()}`}>
      {memoizedTopPanel}

      <div className={`smog-overlay ${state.pollution > 50 ? 'smog-active' : ''}`} style={{ opacity: state.pollution > 50 ? (state.pollution - 50) / 50 : 0 }}></div>

      {showTutorial && <TutorialOverlay onClose={() => setShowTutorial(false)} />}

      {view === 'LOGS' && <LogPage state={state} onBack={() => setView('GAME')} />}

      {/* 传递正确的投票处理函数 */}
      {view === 'VOTE' && (
        <VotePage 
          state={state} 
          onBack={() => setView('GAME')} 
          onSubmitVote={handleSubmitVote} 
          onInitiateVote={handleInitiateVote} 
        />
      )}

      {view === 'CHILD_FEEDBACK' && <ChildFeedbackPage state={state} onBack={() => setView('GAME')} />}
      {view === 'TEACHER_REPORT' && <TeacherReportPage state={state} onBack={() => setView('GAME')} />}

      <main className="flex flex-1 overflow-hidden">
        {memoizedSidebarLeft}

        <div className="flex-1 flex flex-col relative">
          <GameMap 
            map={state.map}
            isPowered={state.power <= state.powerCapacity}
            onCellClick={handleCellClick}
            selectedBuildingId={selectedBuildingId}
            focusedCell={focusedCell}
          />

          {focusedCell && (
            <BuildingInfoOverlay 
              cell={focusedCell} onClose={() => setFocusedCell(null)} onDemolish={handleDemolish}
            />
          )}

          <div className="absolute top-6 left-6 flex items-center gap-3 bg-white/95 p-3 rounded-2xl shadow-xl border border-gray-100 backdrop-blur-sm">
            <div className="bg-indigo-100 p-2 rounded-xl text-indigo-600">
               <span className="text-xl font-bold">#1</span>
            </div>
            <div>
              <span className="text-[10px] text-gray-400 block font-bold uppercase tracking-widest">当前活跃角色</span>
              <button onClick={switchRole} className="font-bold text-gray-800 hover:text-indigo-600 transition-colors flex items-center gap-1">
