export const LogPage: React.FC<LogPageProps> = ({ state, onBack }) => {
  const exportJSON = () => {
    const dataStr = JSON.stringify(state.logs, null, 2);
    const dataUri = 'data:application/json;charset=utf-8,' + encodeURIComponent(dataStr);
    const exportFileDefaultName = `${state.sessionId}_logs.json`;

    const linkElement = document.createElement('a');
    linkElement.setAttribute('href', dataUri);
    linkElement.setAttribute('download', exportFileDefaultName);
    linkElement.click();
  };

  const exportCSV = () => {
    const headers = [
      'Timestamp',
      'Player ID',
      'Event Type',
      'Building Type',
      'Coordinates',
      'Public Facility',
      'Target Owner ID',
      'Vote Option',
      'Discuss Tag',
      'Problem ID'
    ];

    const rows = state.logs.map(log => [
      `${log.timestamp}s`,
      log.player_id,
      log.event_type,
      log.building_type || 'N/A',
      Array.isArray(log.coordinates) ? `"${log.coordinates[0]}, ${log.coordinates[1]}"` : (log.coordinates || 'N/A'),
