      log.discuss_tag ? `"${log.discuss_tag.replace(/"/g, '""')}"` : 'N/A',
      log.problem_id || 'N/A'
    ]);

    const csvContent = [
      headers.join(','),
      ...rows.map(row => row.join(','))
