import React, { useState } from 'react';
import { GameState, LogEvent, SessionData } from '../types';

interface LogPageProps {
  state: GameState;
  archivedSessions: SessionData[];
  onBack: () => void;
}

export const LogPage: React.FC<LogPageProps> = ({ state, archivedSessions, onBack }) => {
  // Use state to track which session's logs we are viewing. Default is 'current'
  const [selectedSessionId, setSelectedSessionId] = useState<string>('current');

  // Determine which logs to show
  const getActiveLogs = (): LogEvent[] => {
    if (selectedSessionId === 'current') {
      return state.logs;
    }
    const session = archivedSessions.find(s => s.sessionId === selectedSessionId);
    return session ? session.logs : [];
  };

  const activeLogs = getActiveLogs();
  const currentDisplaySessionId = selectedSessionId === 'current' ? state.sessionId : selectedSessionId;
  const currentDisplayGroupId = selectedSessionId === 'current' ? state.groupId : archivedSessions.find(s => s.sessionId === selectedSessionId)?.groupId || 'N/A';

  const exportJSON = () => {
    const dataStr = JSON.stringify(activeLogs, null, 2);
    const dataUri = 'data:application/json;charset=utf-8,' + encodeURIComponent(dataStr);
    const exportFileDefaultName = `${currentDisplaySessionId}_logs.json`;

    const linkElement = document.createElement('a');
    linkElement.setAttribute('href', dataUri);
    linkElement.setAttribute('download', exportFileDefaultName);
    linkElement.click();
  };

  const exportCSV = () => {
    const headers = [
      'Timestamp',
      'Player ID',
      'Event Type',
      'Building Type',
      'Coordinates',
      'Public Facility',
      'Target Owner ID',
      'Vote Option',
      'Discuss Tag',
      'Problem ID'
    ];

    const rows = activeLogs.map(log => [
      `${log.timestamp}s`,
      log.player_id,
      log.event_type,
      log.building_type || 'N/A',
      Array.isArray(log.coordinates) ? `"${log.coordinates[0]}, ${log.coordinates[1]}"` : (log.coordinates || 'N/A'),
      log.is_public !== undefined ? log.is_public : 'N/A',
      log.target_owner_id || 'N/A',
      log.vote_option_id || 'N/A',
      log.discuss_tag ? `"${log.discuss_tag.replace(/"/g, '""')}"` : 'N/A',
      log.problem_id || 'N/A'
    ]);

    const csvContent = [
      headers.join(','),
      ...rows.map(row => row.join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', `${currentDisplaySessionId}_logs.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const getEventBadge = (type: LogEvent['event_type']) => {
    const colors: Record<string, string> = {
      propose: 'bg-green-100 text-green-700',
      modify_own: 'bg-blue-100 text-blue-700',
      modify_other: 'bg-red-100 text-red-700 border border-red-200',
      vote: 'bg-purple-100 text-purple-700',
      discuss: 'bg-pink-100 text-pink-700',
      solve: 'bg-yellow-100 text-yellow-700 border border-yellow-300',
    };
    return <span className={`px-2 py-1 rounded-full text-[10px] font-bold uppercase ${colors[type] || 'bg-gray-100 text-gray-600'}`}>{type}</span>;
  };

  return (
    <div className="fixed inset-0 z-[200] bg-gray-50 flex flex-col animate-in fade-in slide-in-from-bottom-4 duration-300">
      {/* Top Header Information Bar */}
      <header className="bg-white border-b border-gray-200 px-8 py-4 flex items-center justify-between shadow-sm">
        <div className="flex items-center gap-8">
          <button onClick={onBack} className="text-gray-400 hover:text-indigo-600 flex items-center gap-2 font-bold transition-colors">
            <span className="text-xl">←</span> 返回游戏
          </button>
          <div className="h-8 w-px bg-gray-200"></div>

          <div className="flex gap-4 items-center">
             <div className="flex flex-col">
                <span className="text-[10px] text-gray-400 font-bold uppercase tracking-wider">选择查看的小组 (Select Group)</span>
                <select 
                  value={selectedSessionId} 
                  onChange={(e) => setSelectedSessionId(e.target.value)}
                  className="font-bold text-gray-800 border-none bg-transparent outline-none cursor-pointer hover:bg-gray-50 p-1 rounded"
                >
                  <option value="current">🔴 当前进行中: {state.sessionId} ({state.groupId})</option>
                  {archivedSessions.map((session) => (
                    <option key={session.sessionId} value={session.sessionId}>
                      📦 存档: {session.sessionId} ({session.groupId})
                    </option>
                  ))}
                </select>
             </div>
          </div>

          <div className="h-8 w-px bg-gray-200"></div>
          <div className="flex gap-6">
            <div className="flex flex-col">
              <span className="text-[10px] text-gray-400 font-bold uppercase tracking-wider">Group ID</span>
              <span className="font-bold text-gray-800">{currentDisplayGroupId}</span>
            </div>
          </div>
        </div>
        <div className="flex gap-3">
          <button 
            onClick={exportCSV}
            className="bg-emerald-600 hover:bg-emerald-700 text-white px-5 py-2 rounded-xl font-bold shadow-lg shadow-emerald-100 transition-all flex items-center gap-2"
          >
            <span>📄</span> 导出 CSV
          </button>
          <button 
            onClick={exportJSON}
            className="bg-indigo-600 hover:bg-indigo-700 text-white px-5 py-2 rounded-xl font-bold shadow-lg shadow-indigo-100 transition-all flex items-center gap-2"
          >
            <span>📦</span> 导出 JSON
          </button>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 overflow-hidden flex flex-col p-8 gap-6">
        {/* Quick Stats */}
        <div className="grid grid-cols-3 gap-6">
          <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
            <span className="text-gray-400 text-xs font-bold uppercase block mb-1">总事件数 (Total Events)</span>
            <span className="text-3xl font-black text-gray-800">{activeLogs.length}</span>
          </div>
          <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
             <span className="text-gray-400 text-xs font-bold uppercase block mb-1">当前查看会话 (Session)</span>
             <span className="text-lg font-bold text-indigo-600 break-all">{currentDisplaySessionId}</span>
          </div>
          <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
             <span className="text-gray-400 text-xs font-bold uppercase block mb-1">存档时间</span>
             <span className="text-xl font-black text-gray-800">
               {selectedSessionId === 'current' ? '实时进行中' : new Date(archivedSessions.find(s => s.sessionId === selectedSessionId)?.timestamp || 0).toLocaleString()}
             </span>
          </div>
        </div>

        {/* Logs Table */}
        <div className="flex-1 bg-white rounded-2xl shadow-sm border border-gray-100 flex flex-col overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-left border-collapse">
              <thead className="bg-gray-50 text-[10px] font-bold text-gray-400 uppercase tracking-widest sticky top-0 z-10">
                <tr>
                  <th className="px-6 py-4 border-b border-gray-100">Timestamp</th>
                  <th className="px-6 py-4 border-b border-gray-100">Player ID</th>
                  <th className="px-6 py-4 border-b border-gray-100">Event Type</th>
                  <th className="px-6 py-4 border-b border-gray-100">Details / Tag</th>
                  <th className="px-6 py-4 border-b border-gray-100">Coordinates</th>
                  <th className="px-6 py-4 border-b border-gray-100">Public</th>
                  <th className="px-6 py-4 border-b border-gray-100">Target</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50 text-sm">
                {activeLogs.length === 0 ? (
                  <tr>
                    <td colSpan={7} className="px-6 py-20 text-center text-gray-400 italic">暂无记录行为...</td>
                  </tr>
                ) : (
                  [...activeLogs].reverse().map((log, i) => (
                    <tr key={i} className="hover:bg-indigo-50/30 transition-colors">
                      <td className="px-6 py-4 font-mono text-gray-500">{log.timestamp}s</td>
                      <td className="px-6 py-4 font-bold text-gray-700">{log.player_id}</td>
                      <td className="px-6 py-4">{getEventBadge(log.event_type)}</td>
                      <td className="px-6 py-4 text-gray-600 max-w-xs truncate" title={log.discuss_tag || log.building_type}>
                        {log.discuss_tag || log.building_type || 'N/A'}
                      </td>
                      <td className="px-6 py-4 text-gray-600 font-mono">
                        {Array.isArray(log.coordinates) ? `(${log.coordinates[0]}, ${log.coordinates[1]})` : log.coordinates}
                      </td>
                      <td className="px-6 py-4">
                        <span className={`px-2 py-0.5 rounded text-[10px] font-bold ${log.is_public === true ? 'bg-green-50 text-green-600' : log.is_public === false ? 'bg-gray-50 text-gray-400' : 'text-gray-300'}`}>
                          {log.is_public === true ? 'TRUE' : log.is_public === false ? 'FALSE' : '-'}
                        </span>
                      </td>
                      <td className="px-6 py-4 text-gray-400 font-medium">{log.target_owner_id || '-'}</td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>
      </main>

      <footer className="bg-white border-t border-gray-100 px-8 py-4 text-[10px] text-gray-300 font-bold flex justify-between uppercase tracking-widest">
        <span>EcoCity Log System v1.2 - Enhanced</span>
        <span>Generated at {new Date().toLocaleString()}</span>
      </footer>
    </div>
  );
};

import React from 'react';
import { GameState, SessionData } from '../types';

interface TeacherReportPageProps {
  state: GameState;
  archivedSessions: SessionData[];
  onBack: () => void;
}

export const TeacherReportPage: React.FC<TeacherReportPageProps> = ({ state, archivedSessions, onBack }) => {

  // Helper to calculate stats for a single set of logs
  const calculateGroupStats = (logs: any[]) => {
    return {
      propose: logs.filter(l => l.event_type === 'propose').length,
      modify: logs.filter(l => l.event_type === 'modify_own' || l.event_type === 'modify_other').length,
      vote: logs.filter(l => l.event_type === 'vote').length,
      discuss: logs.filter(l => l.event_type === 'discuss').length,
      solve: logs.filter(l => l.event_type === 'solve').length
    };
  };

  const determineGroupType = (stats: any) => {
    if (stats.modify > 5 && stats.vote > 3) return { label: 'Highly Collaborative', color: 'text-green-600 bg-green-50' };
    if (stats.modify < 2 && stats.propose > 5) return { label: 'Builders', color: 'text-orange-600 bg-orange-50' };
    if (stats.propose < 3) return { label: 'Low Participation', color: 'text-gray-600 bg-gray-50' };
    return { label: 'Balanced', color: 'text-indigo-600 bg-indigo-50' };
  };

  // 1. Current Session Data
  const currentStats = calculateGroupStats(state.logs);
  const currentGroupType = determineGroupType(currentStats);
  const currentSessionData = {
    name: `${state.groupId} (进行中)`,
    sessionId: state.sessionId,
    ...currentStats,
    type: currentGroupType.label,
    typeColor: currentGroupType.color,
    isCurrent: true
  };

  // 2. Archived Sessions Data
  const archivedStats = archivedSessions.map(session => {
    const stats = calculateGroupStats(session.logs);
    const type = determineGroupType(stats);
    return {
      name: `${session.groupId} (存档)`,
      sessionId: session.sessionId,
      ...stats,
      type: type.label,
      typeColor: type.color,
      isCurrent: false
    };
  });

  // Combine all data
  const allGroupsData = [currentSessionData, ...archivedStats];

  // Calculate totals for summary cards
  const totalPropose = allGroupsData.reduce((acc, curr) => acc + curr.propose, 0);
  const totalModify = allGroupsData.reduce((acc, curr) => acc + curr.modify, 0);
  const totalVote = allGroupsData.reduce((acc, curr) => acc + curr.vote, 0);
  const totalDiscuss = allGroupsData.reduce((acc, curr) => acc + curr.discuss, 0);
  const totalSolve = allGroupsData.reduce((acc, curr) => acc + curr.solve, 0);

  return (
    <div className="fixed inset-0 z-[250] bg-slate-50 flex flex-col animate-in fade-in duration-500 overflow-y-auto">
      <header className="bg-slate-900 text-white px-10 py-8 flex items-center justify-between shadow-2xl sticky top-0 z-10">
        <div>
          <h1 className="text-3xl font-black tracking-tight">小组五维公民行为分析 (Dashboard)</h1>
          <p className="text-slate-400 font-bold mt-1 uppercase text-xs tracking-widest">
             总计记录小组数: {allGroupsData.length}
          </p>
        </div>
        <button onClick={onBack} className="bg-slate-800 hover:bg-slate-700 text-white px-8 py-3 rounded-2xl font-black border border-slate-700 transition-all">
          关闭报告
        </button>
      </header>

      <main className="max-w-7xl mx-auto w-full p-10 space-y-10">
        {/* 数据统计概览 (Across ALL sessions) */}
        <section className="grid grid-cols-5 gap-6">
          <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 flex flex-col items-center justify-center text-center">
            <h4 className="text-slate-400 font-bold uppercase text-[10px] tracking-widest mb-2">PROPOSE (TOTAL)</h4>
            <div className="text-4xl font-black text-blue-500">{totalPropose}</div>
            <p className="text-xs text-slate-400 mt-1">总提出方案</p>
          </div>
          <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 flex flex-col items-center justify-center text-center">
            <h4 className="text-slate-400 font-bold uppercase text-[10px] tracking-widest mb-2">MODIFY (TOTAL)</h4>
            <div className="text-4xl font-black text-amber-500">{totalModify}</div>
            <p className="text-xs text-slate-400 mt-1">总协作修改</p>
          </div>
          <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 flex flex-col items-center justify-center text-center">
            <h4 className="text-slate-400 font-bold uppercase text-[10px] tracking-widest mb-2">VOTE (TOTAL)</h4>
            <div className="text-4xl font-black text-purple-500">{totalVote}</div>
            <p className="text-xs text-slate-400 mt-1">总参与决策</p>
          </div>
          <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 flex flex-col items-center justify-center text-center">
            <h4 className="text-slate-400 font-bold uppercase text-[10px] tracking-widest mb-2">DISCUSS (TOTAL)</h4>
            <div className="text-4xl font-black text-pink-500">{totalDiscuss}</div>
            <p className="text-xs text-slate-400 mt-1">总协商讨论</p>
          </div>
          <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 flex flex-col items-center justify-center text-center">
            <h4 className="text-slate-400 font-bold uppercase text-[10px] tracking-widest mb-2">SOLVE (TOTAL)</h4>
            <div className="text-4xl font-black text-emerald-500">{totalSolve}</div>
            <p className="text-xs text-slate-400 mt-1">总解决问题</p>
          </div>
        </section>

        {/* 核心对比表格 */}
        <section className="bg-white rounded-[32px] shadow-sm border border-slate-200 overflow-hidden">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-8 py-6 text-xs font-black text-slate-400 uppercase tracking-widest w-1/4">小组名称 (Group)</th>
                <th className="px-4 py-6 text-xs font-black text-blue-400 uppercase tracking-widest text-center">Propose</th>
                <th className="px-4 py-6 text-xs font-black text-amber-400 uppercase tracking-widest text-center">Modify</th>
                <th className="px-4 py-6 text-xs font-black text-purple-400 uppercase tracking-widest text-center">Vote</th>
                <th className="px-4 py-6 text-xs font-black text-pink-400 uppercase tracking-widest text-center">Discuss</th>
                <th className="px-4 py-6 text-xs font-black text-emerald-400 uppercase tracking-widest text-center">Solve</th>
                <th className="px-8 py-6 text-xs font-black text-slate-400 uppercase tracking-widest text-right">行为模式</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {allGroupsData.map((group, i) => (
                <tr key={i} className={`transition-colors ${group.isCurrent ? 'bg-indigo-50/50' : 'hover:bg-slate-50/50'}`}>
                  <td className="px-8 py-6">
                    <div className="font-black text-slate-800">{group.name}</div>
                    <div className="text-[10px] text-slate-400">{group.sessionId}</div>
                  </td>
                  <td className="px-4 py-6 font-bold text-slate-600 text-center">{group.propose}</td>
                  <td className="px-4 py-6 font-bold text-slate-600 text-center">{group.modify}</td>
                  <td className="px-4 py-6 font-bold text-slate-600 text-center">{group.vote}</td>
                  <td className="px-4 py-6 font-bold text-slate-600 text-center">{group.discuss}</td>
                  <td className="px-4 py-6 font-bold text-slate-600 text-center">{group.solve}</td>
                  <td className="px-8 py-6 text-right">
                    <span className={`px-4 py-1.5 rounded-full text-xs font-black uppercase ${group.typeColor}`}>
                      {group.type}
                    </span>
                  </td>
                </tr>
              ))}
              {allGroupsData.length === 0 && (
                <tr>
                  <td colSpan={7} className="px-8 py-10 text-center text-slate-400 italic">暂无小组数据</td>
                </tr>
              )}
            </tbody>
          </table>
        </section>

        {/* 可视化对比 (Example: Modify vs Solve) */}
        <section className="grid grid-cols-2 gap-10">
          <div className="bg-white p-10 rounded-[32px] border border-slate-100 shadow-sm">
            <h3 className="text-lg font-black text-slate-800 mb-8">协作修改量对比 (Modify)</h3>
            <div className="space-y-6">
              {allGroupsData.map((group, i) => (
                <div key={i} className="flex items-center gap-4">
                  <span className="w-32 text-xs font-bold text-slate-500 uppercase truncate">{group.name}</span>
                  <div className="flex-1 h-4 bg-slate-100 rounded-full overflow-hidden">
                    <div 
                      className={`h-full rounded-full ${group.isCurrent ? 'bg-amber-500' : 'bg-slate-300'}`} 
                      style={{ width: `${Math.min(100, group.modify * 10)}%` }}
                    ></div>
                  </div>
                  <span className="w-8 text-right font-black text-slate-800">{group.modify}</span>
                </div>
              ))}
            </div>
          </div>

          <div className="bg-white p-10 rounded-[32px] border border-slate-100 shadow-sm">
             <h3 className="text-lg font-black text-slate-800 mb-8">问题解决能力对比 (Solve)</h3>
            <div className="space-y-6">
              {allGroupsData.map((group, i) => (
                <div key={i} className="flex items-center gap-4">
                  <span className="w-32 text-xs font-bold text-slate-500 uppercase truncate">{group.name}</span>
                  <div className="flex-1 h-4 bg-slate-100 rounded-full overflow-hidden">
                    <div 
                      className={`h-full rounded-full ${group.isCurrent ? 'bg-emerald-500' : 'bg-slate-300'}`} 
                      style={{ width: `${Math.min(100, group.solve * 20)}%` }}
                    ></div>
                  </div>
                  <span className="w-8 text-right font-black text-slate-800">{group.solve}</span>
                </div>
              ))}
            </div>
          </div>
        </section>
      </main>
    </div>
  );
};

