import React, { useState, useEffect, useCallback, useRef, useMemo } from 'react';
import { GameState, Phase, Role, Task, Feedback, MapCell, LogEvent, ViewState, VoteData, SessionData } from './types';
import { INITIAL_STATE, BUILDINGS, GRID_SIZE, ROLE_INFO } from './constants';
import { TopPanel } from './components/TopPanel';
import { GameMap } from './components/Map';
import { SidebarLeft } from './components/SidebarLeft';
import { SidebarRight } from './components/SidebarRight';
import { BuildingInfoOverlay } from './components/BuildingInfoOverlay';
import { LogPage } from './components/LogPage';
import { VotePage } from './components/VotePage';
import { TutorialOverlay } from './components/TutorialOverlay';
import { ChildFeedbackPage } from './components/ChildFeedbackPage';
import { TeacherReportPage } from './components/TeacherReportPage';
import { HomePage } from './components/HomePage';
import { getAIAdvice, generateFeedback, speakAdvice } from './services/geminiService';

const App: React.FC = () => {
  // 核心游戏状态：地图、日志、当前角色、当前阶段
  const [state, setState] = useState<GameState>({ ...INITIAL_STATE, groupId: '', customPlayerId: '' });

  // 历史存档：存储所有玩过的小组记录 (Persistence could be added via localStorage)
  const [archivedSessions, setArchivedSessions] = useState<SessionData[]>(() => {
    const saved = localStorage.getItem('ecoCity_sessions');
    return saved ? JSON.parse(saved) : [];
  });

  // 视图状态：默认为首页
  const [view, setView] = useState<ViewState>('HOME');
  const [showTutorial, setShowTutorial] = useState(false);

  // 交互状态：选中建筑、选中的单元格
  const [selectedBuildingId, setSelectedBuildingId] = useState<string | null>(null);
  const [focusedCell, setFocusedCell] = useState<MapCell | null>(null);

  const selectedBuildingRef = useRef<string | null>(null);
  useEffect(() => { selectedBuildingRef.current = selectedBuildingId; }, [selectedBuildingId]);

  const stateRef = useRef(state);
  useEffect(() => { stateRef.current = state; }, [state]);

  const lastCriticalAlertRef = useRef<number>(0);

  const [tasks, setTasks] = useState<Task[]>([
    { id: '1', title: '让所有住宅 4 格内至少有一所学校', completed: false, type: 'daily' },
    { id: '2', title: '城市总人口达到 500人', completed: false, type: 'urgent' },
    { id: '3', title: '污染指数降低至 20% 或以下 🌍', completed: false, type: 'daily' }
  ]);
  const [feedbacks, setFeedbacks] = useState<Feedback[]>([
    { id: '1', author: '市民A', text: '这边的电力供应看起来不太稳定', time: '16:04', avatar: 'https://picsum.photos/32/32?random=1' },
    { id: '2', author: '市民B', text: '我们需要更多绿化空间！', time: '16:30', avatar: 'https://picsum.photos/32/32?random=2' }
  ]);
  const [aiAdvice, setAiAdvice] = useState<string>("正在分析城市数据...");

  // --- Session Management ---

  // 1. Start Game: Initialize state from Home Page inputs
  const handleStartGame = (sessionId: string, groupId: string, playerId: string, role: Role) => {
    setState({
      ...INITIAL_STATE,
      sessionId,
      groupId,
      customPlayerId: playerId,
      currentRole: role,
      startTime: Date.now(),
      logs: []
    });
    setTasks([
      { id: '1', title: '让所有住宅 4 格内至少有一所学校', completed: false, type: 'daily' },
      { id: '2', title: '城市总人口达到 500人', completed: false, type: 'urgent' },
      { id: '3', title: '污染指数降低至 20% 或以下 🌍', completed: false, type: 'daily' }
    ]);
    setView('GAME');
    setShowTutorial(true);
  };

  // 2. End/Archive Session: Save current state to history and return to Home
  const handleEndSession = () => {
    if (!window.confirm("确定要结束当前小组并返回首页吗？这将保存当前小组的记录。")) return;

    const sessionData: SessionData = {
      sessionId: state.sessionId,
      groupId: state.groupId,
      logs: state.logs,
      timestamp: Date.now()
    };

    const newArchives = [...archivedSessions, sessionData];
    setArchivedSessions(newArchives);
    localStorage.setItem('ecoCity_sessions', JSON.stringify(newArchives));

    // Reset necessary state
    setSelectedBuildingId(null);
    setFocusedCell(null);
    setView('HOME');
  };

  // --- Game Logic ---

  const cityStats = useMemo(() => {
    let goldDelta = 0;
    let powerUsed = 0;
    let powerCapacity = 0;
    let totalPollution = 20;
    let pop = 0;
    let targetHappiness = 0;

    state.map.flat().forEach(cell => {
      if (cell.buildingId || cell.isRoad) {
        const b = cell.buildingId ? BUILDINGS[cell.buildingId] : BUILDINGS['ROAD'];
        goldDelta += b.goldEffect;
        if (b.powerEffect > 0) powerCapacity += b.powerEffect;
        else powerUsed -= b.powerEffect;
        totalPollution += b.pollutionEffect;
        pop += b.popEffect;
        targetHappiness += b.happinessEffect;
      }
    });

    return { goldDelta, powerUsed, powerCapacity, totalPollution, pop, targetHappiness };
  }, [state.map]);

  useEffect(() => {
    // Only run critical alerts in GAME view
    if (view !== 'GAME') return;

    const isCriticalPower = cityStats.powerUsed > cityStats.powerCapacity;
    const isCriticalPollution = cityStats.totalPollution > 50;

    if ((isCriticalPower || isCriticalPollution) && Date.now() - lastCriticalAlertRef.current > 45000) {
       lastCriticalAlertRef.current = Date.now();
       const msg = isCriticalPower ? "警告：城市电力不足，部分区域运转受限。" : "警告：污染水平过高，请立即增加绿化设施。";
       speakAdvice(msg);
    }
  }, [cityStats, view]);

  useEffect(() => {
    if (view !== 'GAME') return;
    const fetchAdvice = async () => {
      const advice = await getAIAdvice(state);
      setAiAdvice(advice);
    };
    fetchAdvice();
  }, [state.phase, state.day, view]);

  useEffect(() => {
    if (view !== 'GAME') return;

    const timer = setInterval(() => {
      setState(prev => {
        const nextTimer = prev.timer > 0 ? prev.timer - 1 : 120;
        let nextPhase = prev.phase;
        let nextDay = prev.day;

        if (prev.timer === 0) {
          if (prev.phase === Phase.BUILD) nextPhase = Phase.VOTE;
          else if (prev.phase === Phase.VOTE) nextPhase = Phase.DISCUSS;
          else {
            nextPhase = Phase.BUILD;
            nextDay += 1;
          }
        }

        const goldUpdate = prev.timer % 10 === 0 ? prev.goldDelta : 0;

        return {
          ...prev,
          timer: nextTimer,
          phase: nextPhase,
          day: nextDay,
          gold: prev.gold + goldUpdate,
          happiness: Math.min(100, Math.max(0, prev.happiness + (prev.happiness < 50 ? -1 : 1))) 
        };
      });
    }, 1000);

    return () => clearInterval(timer);
  }, [view]); 

  useEffect(() => {
    setState(prev => ({
      ...prev,
      goldDelta: cityStats.goldDelta,
      population: cityStats.pop,
      power: cityStats.powerUsed,
      powerCapacity: cityStats.powerCapacity,
      pollution: Math.max(0, Math.min(100, cityStats.totalPollution)),
    }));
  }, [cityStats]);

  useEffect(() => {
    setTasks(prevTasks => {
      let hasChanges = false;
      const newTasks = prevTasks.map(t => {
        if (t.completed) return t;

        let completed = false;
        if (t.id === '1') {
          const flatMap = state.map.flat();
          const residences = flatMap.filter(c => c.buildingId === 'RESIDENCE');
          const schools = flatMap.filter(c => c.buildingId === 'SCHOOL');
          if (residences.length > 0) {
            completed = residences.every(r => schools.some(s => (Math.abs(r.x - s.x) + Math.abs(r.y - s.y)) <= 4));
          }
        }
        else if (t.id === '2' && state.population >= 500) completed = true;
        else if (t.id === '3' && state.pollution <= 20) completed = true;

        if (completed) {
          hasChanges = true;
          return { ...t, completed: true };
        }
        return t;
      });

      if (hasChanges) {
        const newlyCompleted = newTasks.filter(nt => !prevTasks.find(pt => pt.id === nt.id)?.completed);
        newlyCompleted.forEach(task => {
           setState(current => ({
             ...current,
             logs: [...current.logs, {
               session_id: current.sessionId,
               timestamp: Math.floor((Date.now() - current.startTime) / 1000),
               player_id: current.currentRole, // Use role for logic, but log should theoretically reflect player ID too
               event_type: 'solve',
               problem_id: task.id,
               discuss_tag: `Completed: ${task.title}`
             }]
           }));
        });
      }

      return hasChanges ? newTasks : prevTasks;
    });
  }, [state.population, state.pollution, state.map]);

  const handleCellClick = useCallback((x: number, y: number) => {
    const currentState = stateRef.current;
    const bId = selectedBuildingRef.current;
    const cell = currentState.map[y][x];

    if (cell.buildingId || cell.isRoad) {
      setFocusedCell(cell);
      return;
    }

    if (bId && !cell.buildingId && !cell.isRoad && currentState.phase === Phase.BUILD) {
      const building = BUILDINGS[bId];
      if (currentState.gold < building.cost) {
        alert("金币不足！");
        return;
      }

      setState(prev => {
        const currentCell = prev.map[y][x];
        if (currentCell.buildingId || currentCell.isRoad) return prev;

        const newMap = [...prev.map];
        newMap[y] = [...newMap[y]];
        newMap[y][x] = {
          ...newMap[y][x],
          buildingId: bId === 'ROAD' ? null : bId,
          isRoad: bId === 'ROAD',
          ownerId: prev.currentRole
        };

        const newLog: LogEvent = {
          session_id: prev.sessionId,
          timestamp: Math.floor((Date.now() - prev.startTime) / 1000),
          player_id: prev.currentRole,
          event_type: 'propose',
          building_type: bId,
          coordinates: [x, y],
          is_public: building.role === Role.PLANNER || building.role === Role.ENVIRONMENT,
        };

        return {
          ...prev,
          gold: prev.gold - building.cost,
          map: newMap,
          logs: [...prev.logs, newLog]
        };
      });
    }
  }, []);

  const handleDemolish = useCallback((x: number, y: number) => {
    setState(prev => {
      const cell = prev.map[y][x];
      const newMap = [...prev.map];
      newMap[y] = [...newMap[y]];
      newMap[y][x] = { ...newMap[y][x], buildingId: null, isRoad: false, ownerId: null };

      const isOwnBuilding = cell.ownerId === prev.currentRole;
      const eventType = isOwnBuilding ? 'modify_own' : 'modify_other';
      const buildingName = cell.buildingId ? BUILDINGS[cell.buildingId]?.name : 'Road';

      const newLog: LogEvent = {
        session_id: prev.sessionId,
        timestamp: Math.floor((Date.now() - prev.startTime) / 1000),
        player_id: prev.currentRole,
        event_type: eventType,
        building_type: cell.buildingId || 'ROAD',
        coordinates: [x, y],
        target_owner_id: cell.ownerId || 'SYSTEM',
        modification: `Demolished ${buildingName}`
      };

      return { ...prev, map: newMap, logs: [...prev.logs, newLog] };
    });
    setFocusedCell(null);
  }, []);

  const handleRestart = () => {
    if (!window.confirm("确定要重新开始吗？这将清空当前地图和资源。")) return;

    setState(prev => {
      const restartLog: LogEvent = {
        session_id: prev.sessionId,
        timestamp: Math.floor((Date.now() - prev.startTime) / 1000),
        player_id: prev.currentRole,
        event_type: 'propose',
        building_type: '重置游戏',
        coordinates: '全图',
        is_public: true,
      };

      const newMap = Array.from({ length: GRID_SIZE }, (_, y) =>
        Array.from({ length: GRID_SIZE }, (_, x) => ({
          x, y, buildingId: null, isRoad: false, status: 'normal', ownerId: null
        } as MapCell))
      );

      return {
        ...INITIAL_STATE,
        sessionId: prev.sessionId,
        groupId: prev.groupId,
        customPlayerId: prev.customPlayerId,
        startTime: prev.startTime,
        logs: [...prev.logs, restartLog],
        currentRole: prev.currentRole,
        map: newMap
      };
    });

    setSelectedBuildingId(null);
    setFocusedCell(null);
  };

  const handleInitiateVote = (question: string, description: string) => {
    setState(prev => {
      const newVote: VoteData = {
        id: Date.now().toString(),
        question,
        description,
        options: [
          { id: 'plan_A', label: '赞成' },
          { id: 'plan_B', label: '反对' }
        ],
        results: {},
        reasons: {},
        status: 'active',
        initiator: prev.currentRole
      };

      const newLog: LogEvent = {
        session_id: prev.sessionId,
        timestamp: Math.floor((Date.now() - prev.startTime) / 1000),
        player_id: prev.currentRole,
        event_type: 'vote',
        discuss_tag: question,
        vote_option_id: 'INITIATED'
      };

      return {
        ...prev,
        currentVote: newVote,
        logs: [...prev.logs, newLog]
      };
    });
  };

  const handleSubmitVote = (optionId: string, reason?: string) => {
    setState(prev => {
      if (!prev.currentVote) return prev;

      const updatedResults = { ...prev.currentVote.results, [prev.currentRole]: optionId };
      const updatedReasons = reason ? { ...prev.currentVote.reasons, [prev.currentRole]: reason } : prev.currentVote.reasons;

      const newLog: LogEvent = {
        session_id: prev.sessionId,
        timestamp: Math.floor((Date.now() - prev.startTime) / 1000),
        player_id: prev.currentRole,
        event_type: 'vote',
        vote_option_id: optionId
      };

      return {
        ...prev,
        currentVote: {
          ...prev.currentVote,
          results: updatedResults,
          reasons: updatedReasons
        },
        logs: [...prev.logs, newLog]
      };
    });
  };

  const handleSendFeedback = (text: string) => {
    const roleInfo = ROLE_INFO[state.currentRole];
    setFeedbacks(prev => [{
      id: Date.now().toString(), 
      author: roleInfo.name, 
      text: text,
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      avatar: `https://api.dicebear.com/7.x/avataaars/svg?seed=${state.currentRole}`
    }, ...prev.slice(0, 15)]);

    setState(prev => ({
      ...prev,
      logs: [...prev.logs, {
        session_id: prev.sessionId,
        timestamp: Math.floor((Date.now() - prev.startTime) / 1000),
        player_id: prev.currentRole,
        event_type: 'discuss',
        discuss_tag: text
      }]
    }));
  };

  const switchRole = () => {
    setState(prev => {
      const roles = Object.values(Role);
      const nextIndex = (roles.indexOf(prev.currentRole) + 1) % roles.length;
      return { ...prev, currentRole: roles[nextIndex] };
    });
    setSelectedBuildingId(null);
    setFocusedCell(null);
  };

  const getAppBackground = () => {
    if (state.pollution > 60) return 'bg-stone-500';
    if (state.pollution > 40) return 'bg-stone-300';
    return 'bg-blue-50';
  };

  const memoizedSidebarLeft = useMemo(() => (
    <SidebarLeft 
      currentRole={state.currentRole} 
      onSelectBuilding={setSelectedBuildingId}
      selectedId={selectedBuildingId}
      gold={state.gold}
    />
  ), [state.currentRole, selectedBuildingId, state.gold]);

  const memoizedSidebarRight = useMemo(() => (
    <SidebarRight 
      tasks={tasks} aiAdvice={aiAdvice} feedbacks={feedbacks}
      currentRole={state.currentRole}
      onSendFeedback={handleSendFeedback}
      onRewardClick={() => { setState(prev => ({ ...prev, gold: prev.gold + 500 })); alert("获得政府奖励金！"); }}
    />
  ), [tasks, aiAdvice, feedbacks, state.currentRole]);

  if (view === 'HOME') {
    return <HomePage onStartGame={handleStartGame} />;
  }

  return (
    <div className={`flex flex-col h-screen w-full transition-colors duration-[3000ms] select-none ${getAppBackground()}`}>
      <TopPanel state={state} onHomeClick={handleEndSession} />

      <div className={`smog-overlay ${state.pollution > 50 ? 'smog-active' : ''}`} style={{ opacity: state.pollution > 50 ? (state.pollution - 50) / 50 : 0 }}></div>

      {showTutorial && <TutorialOverlay onClose={() => setShowTutorial(false)} />}

      {view === 'LOGS' && (
        <LogPage 
          state={state} 
          archivedSessions={archivedSessions}
          onBack={() => setView('GAME')} 
        />
      )}

      {view === 'VOTE' && (
        <VotePage 
          state={state} 
          onBack={() => setView('GAME')} 
          onSubmitVote={handleSubmitVote} 
          onInitiateVote={handleInitiateVote} 
        />
      )}

      {view === 'CHILD_FEEDBACK' && <ChildFeedbackPage state={state} onBack={() => setView('GAME')} />}

      {view === 'TEACHER_REPORT' && (
        <TeacherReportPage 
          state={state} 
          archivedSessions={archivedSessions}
          onBack={() => setView('GAME')} 
        />
      )}

      <main className="flex flex-1 overflow-hidden">
        {memoizedSidebarLeft}

        <div className="flex-1 flex flex-col relative">
          <GameMap 
            map={state.map}
            isPowered={state.power <= state.powerCapacity}
            onCellClick={handleCellClick}
            selectedBuildingId={selectedBuildingId}
            focusedCell={focusedCell}
          />

          {focusedCell && (
            <BuildingInfoOverlay 
              cell={focusedCell} onClose={() => setFocusedCell(null)} onDemolish={handleDemolish}
            />
          )}

          <div className="absolute top-6 left-6 flex items-center gap-3 bg-white/95 p-3 rounded-2xl shadow-xl border border-gray-100 backdrop-blur-sm">
            <div className="bg-indigo-100 p-2 rounded-xl text-indigo-600">
               <span className="text-xl font-bold">#1</span>
            </div>
            <div>
              <span className="text-[10px] text-gray-400 block font-bold uppercase tracking-widest">
                当前角色: {state.customPlayerId}
              </span>
              <button onClick={switchRole} className="font-bold text-gray-800 hover:text-indigo-600 transition-colors flex items-center gap-1">
                 {state.currentRole} <span className="text-xs">🔄</span>
              </button>
            </div>
          </div>

          <div className="h-24 bg-white border-t border-gray-100 flex items-center justify-between px-10 shadow-2xl z-10">
            <div className="flex gap-4">
              <button onClick={() => setShowTutorial(true)} className="w-12 h-12 flex items-center justify-center bg-gray-100 hover:bg-gray-200 text-gray-400 rounded-2xl font-black text-xl transition-all">?</button>
              <button onClick={() => setSelectedBuildingId(null)} className={`px-8 py-3 rounded-2xl font-bold transition-all ${!selectedBuildingId && !focusedCell ? 'bg-indigo-500 text-white shadow-lg' : 'bg-gray-50 text-gray-400'}`}>选择模式</button>
              <button onClick={handleRestart} className="px-8 py-3 rounded-2xl font-bold transition-all bg-rose-100 text-rose-500 hover:bg-rose-200 shadow-sm">重新开始</button>
              <button className={`px-8 py-3 rounded-2xl font-bold transition-all ${selectedBuildingId ? 'bg-yellow-400 text-yellow-900 shadow-lg' : 'bg-gray-50 text-gray-400'}`}>建造模式</button>
            </div>

            <div className="flex gap-8 items-center">
              <button onClick={() => setView('VOTE')} className="group flex flex-col items-center gap-1">
                 <span className="text-2xl">🗳️</span>
                 <span className="text-[10px] font-bold text-gray-400 uppercase">投票</span>
              </button>
              <button onClick={() => setView('CHILD_FEEDBACK')} className="group flex flex-col items-center gap-1">
                 <span className="text-2xl">👤📝</span>
                 <span className="text-[10px] font-bold text-gray-400 uppercase">反馈</span>
              </button>
              <button onClick={() => setView('TEACHER_REPORT')} className="group flex flex-col items-center gap-1">
                 <span className="text-2xl">📊</span>
                 <span className="text-[10px] font-bold text-gray-400 uppercase">报告</span>
              </button>
              <button onClick={() => setView('LOGS')} className="group flex flex-col items-center gap-1">
                 <span className="text-2xl">📝</span>
                 <span className="text-[10px] font-bold text-gray-400 uppercase">日志</span>
              </button>
            </div>
          </div>
        </div>

        {memoizedSidebarRight}
      </main>
    </div>
  );
};

export default App;

import React from 'react';
import { GameState, SessionData } from '../types';

interface TeacherReportPageProps {
  state: GameState;
  archivedSessions: SessionData[];
  onBack: () => void;
}

export const TeacherReportPage: React.FC<TeacherReportPageProps> = ({ state, archivedSessions, onBack }) => {

  // Helper to calculate stats for a single set of logs
  const calculateGroupStats = (logs: any[]) => {
    return {
      propose: logs.filter(l => l.event_type === 'propose').length,
      // Modify count: Counting modify_other as key collaborative metric, but summing both for total activity
      modify: logs.filter(l => l.event_type === 'modify_own' || l.event_type === 'modify_other').length, 
      vote: logs.filter(l => l.event_type === 'vote').length,
      discuss: logs.filter(l => l.event_type === 'discuss').length,
      solve: logs.filter(l => l.event_type === 'solve').length
    };
  };

  const determineGroupType = (stats: any) => {
    if (stats.modify > 5 && stats.vote > 3) return { label: 'Highly Collaborative', color: 'text-green-600 bg-green-50' };
    if (stats.modify < 2 && stats.propose > 5) return { label: 'Builders', color: 'text-orange-600 bg-orange-50' };
    if (stats.propose < 3) return { label: 'Low Participation', color: 'text-gray-600 bg-gray-50' };
    return { label: 'Balanced', color: 'text-indigo-600 bg-indigo-50' };
  };

  // 1. Current Session Data
  const currentStats = calculateGroupStats(state.logs);
  const currentGroupType = determineGroupType(currentStats);
  const currentSessionData = {
    name: `${state.groupId} (进行中)`,
    sessionId: state.sessionId,
    ...currentStats,
    type: currentGroupType.label,
    typeColor: currentGroupType.color,
    isCurrent: true
  };

  // 2. Archived Sessions Data
  const archivedStats = archivedSessions.map(session => {
    const stats = calculateGroupStats(session.logs);
    const type = determineGroupType(stats);
    return {
      name: `${session.groupId} (存档)`,
      sessionId: session.sessionId,
      ...stats,
      type: type.label,
      typeColor: type.color,
      isCurrent: false
    };
  });

  // Combine all data
  const allGroupsData = [currentSessionData, ...archivedStats];

  // Calculate totals for summary cards
  const totalPropose = allGroupsData.reduce((acc, curr) => acc + curr.propose, 0);
  const totalModify = allGroupsData.reduce((acc, curr) => acc + curr.modify, 0);
  const totalVote = allGroupsData.reduce((acc, curr) => acc + curr.vote, 0);
  const totalDiscuss = allGroupsData.reduce((acc, curr) => acc + curr.discuss, 0);
  const totalSolve = allGroupsData.reduce((acc, curr) => acc + curr.solve, 0);

  return (
    <div className="fixed inset-0 z-[250] bg-slate-50 flex flex-col animate-in fade-in duration-500 overflow-y-auto">
      <header className="bg-slate-900 text-white px-10 py-8 flex items-center justify-between shadow-2xl sticky top-0 z-10">
        <div>
          <h1 className="text-3xl font-black tracking-tight">小组五维公民行为分析 (Dashboard)</h1>
          <p className="text-slate-400 font-bold mt-1 uppercase text-xs tracking-widest">
             总计记录小组数: {allGroupsData.length}
          </p>
        </div>
        <button onClick={onBack} className="bg-slate-800 hover:bg-slate-700 text-white px-8 py-3 rounded-2xl font-black border border-slate-700 transition-all">
          关闭报告
        </button>
      </header>

      <main className="max-w-7xl mx-auto w-full p-10 space-y-10">
        {/* 数据统计概览 (Across ALL sessions) */}
        <section className="grid grid-cols-5 gap-6">
          <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 flex flex-col items-center justify-center text-center">
            <h4 className="text-slate-400 font-bold uppercase text-[10px] tracking-widest mb-2">PROPOSE (TOTAL)</h4>
            <div className="text-4xl font-black text-blue-500">{totalPropose}</div>
            <p className="text-xs text-slate-400 mt-1">总提出方案</p>
          </div>
          <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 flex flex-col items-center justify-center text-center">
            <h4 className="text-slate-400 font-bold uppercase text-[10px] tracking-widest mb-2">MODIFY (TOTAL)</h4>
            <div className="text-4xl font-black text-amber-500">{totalModify}</div>
            <p className="text-xs text-slate-400 mt-1">总协作修改</p>
          </div>
          <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 flex flex-col items-center justify-center text-center">
            <h4 className="text-slate-400 font-bold uppercase text-[10px] tracking-widest mb-2">VOTE (TOTAL)</h4>
            <div className="text-4xl font-black text-purple-500">{totalVote}</div>
            <p className="text-xs text-slate-400 mt-1">总参与决策</p>
          </div>
          <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 flex flex-col items-center justify-center text-center">
            <h4 className="text-slate-400 font-bold uppercase text-[10px] tracking-widest mb-2">DISCUSS (TOTAL)</h4>
            <div className="text-4xl font-black text-pink-500">{totalDiscuss}</div>
            <p className="text-xs text-slate-400 mt-1">总协商讨论</p>
          </div>
          <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 flex flex-col items-center justify-center text-center">
            <h4 className="text-slate-400 font-bold uppercase text-[10px] tracking-widest mb-2">SOLVE (TOTAL)</h4>
            <div className="text-4xl font-black text-emerald-500">{totalSolve}</div>
            <p className="text-xs text-slate-400 mt-1">总解决问题</p>
          </div>
        </section>

        {/* 核心对比表格 */}
        <section className="bg-white rounded-[32px] shadow-sm border border-slate-200 overflow-hidden">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-8 py-6 text-xs font-black text-slate-400 uppercase tracking-widest w-1/4">小组名称 (Group)</th>
                <th className="px-4 py-6 text-xs font-black text-blue-400 uppercase tracking-widest text-center">Propose</th>
                <th className="px-4 py-6 text-xs font-black text-amber-400 uppercase tracking-widest text-center">Modify</th>
                <th className="px-4 py-6 text-xs font-black text-purple-400 uppercase tracking-widest text-center">Vote</th>
                <th className="px-4 py-6 text-xs font-black text-pink-400 uppercase tracking-widest text-center">Discuss</th>
                <th className="px-4 py-6 text-xs font-black text-emerald-400 uppercase tracking-widest text-center">Solve</th>
                <th className="px-8 py-6 text-xs font-black text-slate-400 uppercase tracking-widest text-right">行为模式</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {allGroupsData.map((group, i) => (
                <tr key={i} className={`transition-colors ${group.isCurrent ? 'bg-indigo-50/50' : 'hover:bg-slate-50/50'}`}>
                  <td className="px-8 py-6">
                    <div className="font-black text-slate-800">{group.name}</div>
                    <div className="text-[10px] text-slate-400">{group.sessionId}</div>
                  </td>
                  <td className="px-4 py-6 font-bold text-slate-600 text-center">{group.propose}</td>
                  <td className="px-4 py-6 font-bold text-slate-600 text-center">{group.modify}</td>
                  <td className="px-4 py-6 font-bold text-slate-600 text-center">{group.vote}</td>
                  <td className="px-4 py-6 font-bold text-slate-600 text-center">{group.discuss}</td>
                  <td className="px-4 py-6 font-bold text-slate-600 text-center">{group.solve}</td>
                  <td className="px-8 py-6 text-right">
                    <span className={`px-4 py-1.5 rounded-full text-xs font-black uppercase ${group.typeColor}`}>
                      {group.type}
                    </span>
                  </td>
                </tr>
              ))}
              {allGroupsData.length === 0 && (
                <tr>
                  <td colSpan={7} className="px-8 py-10 text-center text-slate-400 italic">暂无小组数据</td>
                </tr>
              )}
            </tbody>
          </table>
        </section>

        {/* 可视化对比 (Example: Modify vs Solve) */}
        <section className="grid grid-cols-2 gap-10">
          <div className="bg-white p-10 rounded-[32px] border border-slate-100 shadow-sm">
            <h3 className="text-lg font-black text-slate-800 mb-8">协作修改量对比 (Modify)</h3>
            <div className="space-y-6">
              {allGroupsData.map((group, i) => (
                <div key={i} className="flex items-center gap-4">
                  <span className="w-32 text-xs font-bold text-slate-500 uppercase truncate">{group.name}</span>
                  <div className="flex-1 h-4 bg-slate-100 rounded-full overflow-hidden">
                    <div 
                      className={`h-full rounded-full ${group.isCurrent ? 'bg-amber-500' : 'bg-slate-300'}`} 
                      style={{ width: `${Math.min(100, group.modify * 10)}%` }}
                    ></div>
                  </div>
                  <span className="w-8 text-right font-black text-slate-800">{group.modify}</span>
                </div>
              ))}
            </div>
          </div>

          <div className="bg-white p-10 rounded-[32px] border border-slate-100 shadow-sm">
             <h3 className="text-lg font-black text-slate-800 mb-8">问题解决能力对比 (Solve)</h3>
