                placeholder="例如: 2025-01-class1-groupA"
              />
            </div>

            <div>
              <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-2">Group ID (小组名称/编号)</label>
              <input 
                type="text" 
