                  onClose();
                }
              }}
              className={`flex-1 py-4 rounded-2xl font-black text-white shadow-xl transition-all active:scale-95 ${step.color} hover:brightness-110`}
            >
              {currentStep === steps.length - 1 ? "Start Game!" : "Next"}
