import React, { useMemo } from 'react';
import { GameState, Role } from '../types';
import { ROLE_INFO, GRID_SIZE } from '../constants';

interface ChildFeedbackPageProps {
  state: GameState;
  onBack: () => void;
}

export const ChildFeedbackPage: React.FC<ChildFeedbackPageProps> = ({ state, onBack }) => {
  const { currentRole, logs } = state;
  const roleInfo = ROLE_INFO[currentRole];

  // 1. 核心逻辑：只筛选当前角色的日志 (Filter logs for the current role)
  // 当你在主界面左上角切换角色时，state.currentRole 变化，这里的数据也会自动刷新
  const roleLogs = useMemo(() => logs.filter(l => l.player_id === currentRole), [logs, currentRole]);

  // 2. 基础数据统计
  const proposeCount = roleLogs.filter(l => l.event_type === 'propose').length;
  const publicProposeCount = roleLogs.filter(l => l.event_type === 'propose' && l.is_public).length;
  const modifyOwnCount = roleLogs.filter(l => l.event_type === 'modify_own').length;
  const modifyOtherCount = roleLogs.filter(l => l.event_type === 'modify_other').length;
  const voteCount = roleLogs.filter(l => l.event_type === 'vote').length;
  const discussCount = roleLogs.filter(l => l.event_type === 'discuss').length;

  // 3. 三大维度指标计算 (Metrics Calculation)

  // 指标 A: 公共设施关心度 (Public Facility Care)
  // 算法: 公共设施提案数 / 总提案数
  const scorePublic = proposeCount > 0 ? Math.round((publicProposeCount / proposeCount) * 100) : 0;

  const getPublicText = () => {
    if (proposeCount === 0) return "You haven't started building yet. Go build something!";
    if (scorePublic > 60) return "You built many public facilities, considering everyone. Great job!";
    if (scorePublic > 30) return "You addressed some public needs. Keep balancing development.";
    return "Remember to build more facilities that everyone can use (like parks, schools)!";
  };

  // 指标 B: 公平与覆盖度 (Equity & Coverage)
  // 算法: 简单的空间分布分析 (检查建设足迹涉及了多少个象限)
  const touchedQuadrants = new Set<string>();
  roleLogs.filter(l => l.event_type === 'propose' && Array.isArray(l.coordinates)).forEach(l => {
     const [x, y] = l.coordinates as [number, number];
     const qx = x < GRID_SIZE/2 ? 0 : 1;
     const qy = y < GRID_SIZE/2 ? 0 : 1;
     touchedQuadrants.add(`${qx}-${qy}`);
  });
  // 满分代表覆盖了4个象限，最低0
  const scoreCoverage = Math.min(100, (touchedQuadrants.size / 4) * 100);

  const getCoverageText = () => {
     if (scoreCoverage === 100) return "Your buildings cover the whole city fairly!";
     if (scoreCoverage >= 50) return "Some areas are missed. Try spreading buildings out next time.";
     // 特殊反馈：环境专家
     if (currentRole === Role.ENVIRONMENT) return "Some houses are far from parks. Try to bring nature closer to everyone."; 
     return "Your buildings are clustered. Remember to care for remote residents too.";
  };

  // 指标 C: 协同合作程度 (Collaboration Degree)
  // 算法: 加权计算 (修改他人权重最高)
  const collabScoreRaw = (modifyOtherCount * 20) + (voteCount * 10) + (discussCount * 5);
  const scoreCollab = Math.min(100, collabScoreRaw);

  const getCollabText = () => {
    if (scoreCollab > 80) return "Collaboration Master! You often optimize for others and earn trust.";
    if (scoreCollab > 40) return "You help others with facilities, which is great cooperation."; 
    if (scoreCollab > 0) return "Participate more in voting and discussion. Your opinion matters!";
    return "Try modifying others' proposals or expressing views in votes!";
  };

  // 通用组件：进度条卡片
  const Bar = ({ label, score, icon, text, color }: { label: string, score: number, icon: string, text: string, color: string }) => (
    <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm flex flex-col gap-4 animate-in slide-in-from-bottom-4 duration-500">
      <div className="flex items-center gap-4">
        <span className="text-4xl bg-gray-50 p-3 rounded-2xl shrink-0">{icon}</span>
        <div className="flex-1 min-w-0">
          <div className="flex justify-between mb-2">
             <h3 className="font-bold text-gray-700 text-lg">{label}</h3>
             <span className="font-black text-indigo-600 text-xl">{score}%</span>
          </div>
          <div className="h-4 bg-gray-100 rounded-full overflow-hidden">
             <div className={`h-full rounded-full transition-all duration-1000 ease-out ${color}`} style={{ width: `${score}%` }}></div>
          </div>
        </div>
      </div>
      <div className="bg-gray-50 p-4 rounded-2xl text-sm text-gray-600 font-medium leading-relaxed italic border-l-4 border-indigo-200">
        “{text}”
      </div>
    </div>
  );

  return (
    <div className="fixed inset-0 z-[250] bg-indigo-50/95 backdrop-blur-sm flex flex-col animate-in fade-in duration-300 overflow-y-auto">
      {/* 顶部标题区 */}
      <header className="bg-white px-8 py-6 border-b border-gray-200 shadow-sm flex items-center justify-between sticky top-0 z-10">
        <div className="flex items-center gap-4">
          <div className={`w-14 h-14 ${roleInfo.color} rounded-2xl flex items-center justify-center text-3xl shadow-md text-white`}>
            {roleInfo.icon}
          </div>
          <div>
            <h1 className="text-2xl font-black text-gray-800 tracking-tight">Micro-Reflection</h1>
            <p className="text-gray-400 font-bold uppercase text-[10px] tracking-widest mt-1">
               Role: <span className="text-indigo-600 font-black text-sm">{roleInfo.name}</span> • SESSION: {state.sessionId}
            </p>
          </div>
        </div>
        <button onClick={onBack} className="bg-gray-100 hover:bg-gray-200 text-gray-600 px-8 py-3 rounded-2xl font-bold transition-all border-2 border-transparent hover:border-gray-300">
          Close
        </button>
      </header>

      {/* 核心内容区 */}
      <main className="max-w-4xl mx-auto w-full p-8 space-y-8">

        {/* 1. 三大核心指标 (Three Big Bars) */}
        <section className="space-y-6">
           <Bar 
             label="Public Care" 
             score={scorePublic} 
             icon="🏛️" 
             text={getPublicText()} 
             color="bg-emerald-500"
           />
           <Bar 
             label="Equity & Coverage" 
             score={scoreCoverage} 
             icon="🌍" 
             text={getCoverageText()} 
             color="bg-blue-500"
           />
           <Bar 
             label="Collaboration" 
             score={scoreCollab} 
             icon="🤝" 
             text={getCollabText()} 
             color="bg-purple-500"
           />
        </section>

        {/* 2. 详细数据网格 (Detailed Grid) */}
        <section className="grid grid-cols-2 md:grid-cols-4 gap-4">
           <div className="bg-white p-5 rounded-3xl shadow-sm border border-gray-100 text-center flex flex-col justify-center">
              <div className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">My Proposals</div>
              <div className="text-3xl font-black text-gray-800">{proposeCount}</div>
           </div>

           <div className="bg-white p-5 rounded-3xl shadow-sm border border-gray-100 text-center flex flex-col justify-center">
              <div className="text-[10px] font-black text-blue-400 uppercase tracking-widest mb-2">Modify Own</div>
              <div className="text-3xl font-black text-blue-600">{modifyOwnCount}</div>
           </div>

           {/* 重点高亮：协作修改他人 */}
           <div className="bg-purple-50 p-5 rounded-3xl shadow-md border-2 border-purple-100 text-center flex flex-col justify-center transform hover:scale-105 transition-transform">
              <div className="text-[10px] font-black text-purple-500 uppercase tracking-widest mb-2">Modify Others</div>
              <div className="text-3xl font-black text-purple-600">{modifyOtherCount}</div>
           </div>

           <div className="bg-white p-5 rounded-3xl shadow-sm border border-gray-100 text-center flex flex-col justify-center">
              <div className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">Votes & Discuss</div>
              <div className="text-3xl font-black text-gray-800">{voteCount + discussCount}</div>
           </div>
        </section>

      </main>
    </div>
  );
};

import React, { useState, useEffect, useCallback, useRef, useMemo } from 'react';
import { GameState, Phase, Role, Task, Feedback, MapCell, LogEvent, ViewState, VoteData, SessionData } from './types';
import { INITIAL_STATE, BUILDINGS, GRID_SIZE, ROLE_INFO } from './constants';
import { TopPanel } from './components/TopPanel';
import { GameMap } from './components/Map';
import { SidebarLeft } from './components/SidebarLeft';
import { SidebarRight } from './components/SidebarRight';
import { BuildingInfoOverlay } from './components/BuildingInfoOverlay';
import { LogPage } from './components/LogPage';
import { VotePage } from './components/VotePage';
import { TutorialOverlay } from './components/TutorialOverlay';
import { ChildFeedbackPage } from './components/ChildFeedbackPage';
import { TeacherReportPage } from './components/TeacherReportPage';
import { HomePage } from './components/HomePage';
import { ReflectionSurveyPage } from './components/ReflectionSurveyPage';
import { getAIAdvice, generateFeedback, speakAdvice } from './services/geminiService';

const App: React.FC = () => {
  // 核心游戏状态：地图、日志、当前角色、当前阶段
  const [state, setState] = useState<GameState>({ ...INITIAL_STATE, groupId: '', customPlayerId: '' });

  // 历史存档：存储所有玩过的小组记录 (Persistence could be added via localStorage)
  const [archivedSessions, setArchivedSessions] = useState<SessionData[]>(() => {
    try {
      const saved = localStorage.getItem('ecoCity_sessions');
      return saved ? JSON.parse(saved) : [];
    } catch (e) {
      console.error("Failed to load sessions", e);
      return [];
    }
  });

  // 视图状态：默认为首页
  const [view, setView] = useState<ViewState>('HOME');
  const [showTutorial, setShowTutorial] = useState(false);

  // 交互状态：选中建筑、选中的单元格
  const [selectedBuildingId, setSelectedBuildingId] = useState<string | null>(null);
  const [focusedCell, setFocusedCell] = useState<MapCell | null>(null);

  const selectedBuildingRef = useRef<string | null>(null);
  useEffect(() => { selectedBuildingRef.current = selectedBuildingId; }, [selectedBuildingId]);

  const stateRef = useRef(state);
  useEffect(() => { stateRef.current = state; }, [state]);

  const lastCriticalAlertRef = useRef<number>(0);

  const [tasks, setTasks] = useState<Task[]>([
    { id: '1', title: 'Ensure all residences are within 4 tiles of a School', completed: false, type: 'daily' },
    { id: '2', title: 'Reach a population of 500', completed: false, type: 'urgent' },
    { id: '3', title: 'Reduce Pollution below 20% 🌍', completed: false, type: 'daily' }
  ]);
  const [feedbacks, setFeedbacks] = useState<Feedback[]>([
    { id: '1', author: 'Citizen A', text: 'Power supply looks unstable here.', time: '16:04', avatar: 'https://picsum.photos/32/32?random=1' },
    { id: '2', author: 'Citizen B', text: 'We need more green spaces!', time: '16:30', avatar: 'https://picsum.photos/32/32?random=2' }
  ]);
  const [aiAdvice, setAiAdvice] = useState<string>("Analyzing city data...");

  // --- Session Management ---

  // 1. Start Game: Initialize state from Home Page inputs
  const handleStartGame = (sessionId: string, groupId: string, playerId: string, role: Role) => {
    // 强制重新生成地图，确保不共用引用
    const freshMap = Array.from({ length: GRID_SIZE }, (_, y) =>
      Array.from({ length: GRID_SIZE }, (_, x) => ({
        x, y, buildingId: null, isRoad: false, status: 'normal', ownerId: null
      } as MapCell))
    );

    setState({
      ...INITIAL_STATE,
      map: freshMap,
      sessionId,
      groupId,
      customPlayerId: playerId,
      currentRole: role,
      startTime: Date.now(),
      logs: []
    });
    setTasks([
      { id: '1', title: 'Ensure all residences are within 4 tiles of a School', completed: false, type: 'daily' },
      { id: '2', title: 'Reach a population of 500', completed: false, type: 'urgent' },
      { id: '3', title: 'Reduce Pollution below 20% 🌍', completed: false, type: 'daily' }
    ]);
    setView('GAME');
    setShowTutorial(true);
  };

  // 2. End/Archive Session: Save current state to history and return to Home
  const handleEndSession = () => {
    if (!window.confirm("Are you sure you want to end and archive this session?\n\nThis will save the current group data to history and return to the home page for a new group.")) return;

    try {
      const sessionData: SessionData = {
        sessionId: state.sessionId,
        groupId: state.groupId,
        logs: state.logs,
        timestamp: Date.now()
      };

      const newArchives = [...archivedSessions, sessionData];
      setArchivedSessions(newArchives);
      localStorage.setItem('ecoCity_sessions', JSON.stringify(newArchives));
      console.log("Session archived successfully", sessionData);
    } catch (e) {
      console.error("Archive failed", e);
      alert("Archive failed (local storage might be full), but the game will end and return home.");
    }

    // Reset necessary state
    setSelectedBuildingId(null);
    setFocusedCell(null);
    setView('HOME');
  };

  // --- Game Logic ---

  const cityStats = useMemo(() => {
    let goldDelta = 0;
    let powerUsed = 0;
    let powerCapacity = 0;
    let totalPollution = 20;
    let pop = 0;
    let targetHappiness = 0;

    state.map.flat().forEach(cell => {
      if (cell.buildingId || cell.isRoad) {
        const b = cell.buildingId ? BUILDINGS[cell.buildingId] : BUILDINGS['ROAD'];
        goldDelta += b.goldEffect;
        if (b.powerEffect > 0) powerCapacity += b.powerEffect;
        else powerUsed -= b.powerEffect;
        totalPollution += b.pollutionEffect;
        pop += b.popEffect;
        targetHappiness += b.happinessEffect;
      }
    });

    return { goldDelta, powerUsed, powerCapacity, totalPollution, pop, targetHappiness };
  }, [state.map]);

  useEffect(() => {
    // Only run critical alerts in GAME view
    if (view !== 'GAME') return;

    const isCriticalPower = cityStats.powerUsed > cityStats.powerCapacity;
    const isCriticalPollution = cityStats.totalPollution > 50;

    if ((isCriticalPower || isCriticalPollution) && Date.now() - lastCriticalAlertRef.current > 45000) {
       lastCriticalAlertRef.current = Date.now();
       const msg = isCriticalPower ? "Warning: City power is low, some areas are limited." : "Warning: Pollution is too high, increase green facilities immediately.";
       speakAdvice(msg);
    }
  }, [cityStats, view]);

  useEffect(() => {
    if (view !== 'GAME') return;
    const fetchAdvice = async () => {
      const advice = await getAIAdvice(state);
      setAiAdvice(advice);
    };
    fetchAdvice();
  }, [state.phase, state.day, view]);

  useEffect(() => {
    if (view !== 'GAME') return;

    const timer = setInterval(() => {
      setState(prev => {
        const nextTimer = prev.timer > 0 ? prev.timer - 1 : 120;
        let nextPhase = prev.phase;
        let nextDay = prev.day;

        // 修改阶段顺序：建造 -> 讨论 -> 投票 -> 建造(Next Day)
        if (prev.timer === 0) {
          if (prev.phase === Phase.BUILD) {
            nextPhase = Phase.DISCUSS; // 先讨论
          } else if (prev.phase === Phase.DISCUSS) {
            nextPhase = Phase.VOTE;    // 后投票
          } else {
            nextPhase = Phase.BUILD;   // 新的一天
            nextDay += 1;
          }
        }

        const goldUpdate = prev.timer % 10 === 0 ? prev.goldDelta : 0;

        return {
          ...prev,
          timer: nextTimer,
          phase: nextPhase,
          day: nextDay,
          gold: prev.gold + goldUpdate,
          happiness: Math.min(100, Math.max(0, prev.happiness + (prev.happiness < 50 ? -1 : 1))) 
        };
      });
    }, 1000);

    return () => clearInterval(timer);
  }, [view]); 

  useEffect(() => {
    setState(prev => ({
      ...prev,
      goldDelta: cityStats.goldDelta,
      population: cityStats.pop,
      power: cityStats.powerUsed,
      powerCapacity: cityStats.powerCapacity,
      pollution: Math.max(0, Math.min(100, cityStats.totalPollution)),
    }));
  }, [cityStats]);

  useEffect(() => {
    setTasks(prevTasks => {
      let hasChanges = false;
      const newTasks = prevTasks.map(t => {
        if (t.completed) return t;

        let completed = false;
        if (t.id === '1') {
          const flatMap = state.map.flat();
          const residences = flatMap.filter(c => c.buildingId === 'RESIDENCE');
          const schools = flatMap.filter(c => c.buildingId === 'SCHOOL');
          if (residences.length > 0) {
            completed = residences.every(r => schools.some(s => (Math.abs(r.x - s.x) + Math.abs(r.y - s.y)) <= 4));
          }
        }
        else if (t.id === '2' && state.population >= 500) completed = true;
        else if (t.id === '3' && state.pollution <= 20) completed = true;

        if (completed) {
          hasChanges = true;
          return { ...t, completed: true };
        }
        return t;
      });

      if (hasChanges) {
        const newlyCompleted = newTasks.filter(nt => !prevTasks.find(pt => pt.id === nt.id)?.completed);
        newlyCompleted.forEach(task => {
           setState(current => ({
             ...current,
             logs: [...current.logs, {
               session_id: current.sessionId,
               timestamp: Math.floor((Date.now() - current.startTime) / 1000),
               player_id: current.currentRole, // Use role for logic, but log should theoretically reflect player ID too
               event_type: 'solve',
               problem_id: task.id,
               discuss_tag: `Completed: ${task.title}`
             }]
           }));
        });
      }

      return hasChanges ? newTasks : prevTasks;
    });
  }, [state.population, state.pollution, state.map]);

  const handleCellClick = useCallback((x: number, y: number) => {
    const currentState = stateRef.current;
    const bId = selectedBuildingRef.current;
    const cell = currentState.map[y][x];

    if (cell.buildingId || cell.isRoad) {
      setFocusedCell(cell);
      return;
    }

    if (bId && !cell.buildingId && !cell.isRoad && currentState.phase === Phase.BUILD) {
      const building = BUILDINGS[bId];
      if (currentState.gold < building.cost) {
        alert("Not enough gold!");
        return;
      }

      setState(prev => {
        const currentCell = prev.map[y][x];
        if (currentCell.buildingId || currentCell.isRoad) return prev;

        const newMap = [...prev.map];
        newMap[y] = [...newMap[y]];
        newMap[y][x] = {
          ...newMap[y][x],
          buildingId: bId === 'ROAD' ? null : bId,
          isRoad: bId === 'ROAD',
          ownerId: prev.currentRole
        };

        const newLog: LogEvent = {
          session_id: prev.sessionId,
          timestamp: Math.floor((Date.now() - prev.startTime) / 1000),
          player_id: prev.currentRole,
          event_type: 'propose',
          building_type: bId,
          coordinates: [x, y],
          is_public: building.role === Role.PLANNER || building.role === Role.ENVIRONMENT,
        };

        return {
          ...prev,
          gold: prev.gold - building.cost,
          map: newMap,
          logs: [...prev.logs, newLog]
        };
      });
    }
  }, []);

  const handleDemolish = useCallback((x: number, y: number) => {
    setState(prev => {
      const cell = prev.map[y][x];
      const newMap = [...prev.map];
      newMap[y] = [...newMap[y]];
      newMap[y][x] = { ...newMap[y][x], buildingId: null, isRoad: false, ownerId: null };

      const isOwnBuilding = cell.ownerId === prev.currentRole;
      const eventType = isOwnBuilding ? 'modify_own' : 'modify_other';
      const buildingName = cell.buildingId ? BUILDINGS[cell.buildingId]?.name : 'Road';

      const newLog: LogEvent = {
        session_id: prev.sessionId,
        timestamp: Math.floor((Date.now() - prev.startTime) / 1000),
        player_id: prev.currentRole,
        event_type: eventType,
        building_type: cell.buildingId || 'ROAD',
        coordinates: [x, y],
        target_owner_id: cell.ownerId || 'SYSTEM',
        modification: `Demolished ${buildingName}`
      };

      return { ...prev, map: newMap, logs: [...prev.logs, newLog] };
    });
    setFocusedCell(null);
  }, []);

  const handleRestart = () => {
    if (!window.confirm("Are you sure you want to restart this group's game?\n\nNote: This will reset the map but not affect archived sessions.")) return;

    setState(prev => {
      const restartLog: LogEvent = {
        session_id: prev.sessionId,
        timestamp: Math.floor((Date.now() - prev.startTime) / 1000),
        player_id: prev.currentRole,
        event_type: 'propose',
        building_type: 'Reset Game',
        coordinates: 'Global',
        is_public: true,
      };

      const newMap = Array.from({ length: GRID_SIZE }, (_, y) =>
        Array.from({ length: GRID_SIZE }, (_, x) => ({
          x, y, buildingId: null, isRoad: false, status: 'normal', ownerId: null
        } as MapCell))
      );

      return {
        ...INITIAL_STATE,
        sessionId: prev.sessionId,
        groupId: prev.groupId,
        customPlayerId: prev.customPlayerId,
        startTime: prev.startTime,
        logs: [...prev.logs, restartLog],
        currentRole: prev.currentRole,
        map: newMap
      };
    });

    setSelectedBuildingId(null);
    setFocusedCell(null);
  };

  const handleInitiateVote = (question: string, description: string) => {
    setState(prev => {
      const newVote: VoteData = {
        id: Date.now().toString(),
        question,
        description,
        options: [
          { id: 'plan_A', label: 'Yes' },
          { id: 'plan_B', label: 'No' }
        ],
        results: {},
        reasons: {},
        status: 'active',
        initiator: prev.currentRole
      };

      const newLog: LogEvent = {
        session_id: prev.sessionId,
        timestamp: Math.floor((Date.now() - prev.startTime) / 1000),
        player_id: prev.currentRole,
        event_type: 'vote',
        discuss_tag: question,
        vote_option_id: 'INITIATED'
      };

      return {
        ...prev,
        currentVote: newVote,
        logs: [...prev.logs, newLog]
      };
    });
  };

  const handleSubmitVote = (optionId: string, reason?: string) => {
    setState(prev => {
      if (!prev.currentVote) return prev;

      const updatedResults = { ...prev.currentVote.results, [prev.currentRole]: optionId };
      const updatedReasons = reason ? { ...prev.currentVote.reasons, [prev.currentRole]: reason } : prev.currentVote.reasons;

      // 检查是否所有4个角色都投完票了 (Assume 4 roles total)
      const allRolesVoted = Object.keys(updatedResults).length >= 4;

      const newLog: LogEvent = {
        session_id: prev.sessionId,
        timestamp: Math.floor((Date.now() - prev.startTime) / 1000),
        player_id: prev.currentRole,
        event_type: 'vote',
        vote_option_id: optionId
      };

      return {
        ...prev,
        currentVote: {
          ...prev.currentVote,
          results: updatedResults,
          reasons: updatedReasons,
          // 如果所有人都投了，标记为已完成
          status: allRolesVoted ? 'completed' : prev.currentVote.status
        },
        logs: [...prev.logs, newLog]
      };
    });
  };

  // 新增：清空当前投票，允许发起新一轮
  const handleClearVote = () => {
    setState(prev => ({
       ...prev,
       currentVote: null
    }));
  };

  const handleSendFeedback = (text: string) => {
    const roleInfo = ROLE_INFO[state.currentRole];
    setFeedbacks(prev => [{
      id: Date.now().toString(), 
      author: roleInfo.name, 
      text: text,
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      avatar: `https://api.dicebear.com/7.x/avataaars/svg?seed=${state.currentRole}`
    }, ...prev.slice(0, 15)]);

    setState(prev => ({
      ...prev,
      logs: [...prev.logs, {
        session_id: prev.sessionId,
        timestamp: Math.floor((Date.now() - prev.startTime) / 1000),
        player_id: prev.currentRole,
        event_type: 'discuss',
        discuss_tag: text
      }]
    }));
  };

  const switchRole = () => {
    setState(prev => {
      const roles = Object.values(Role);
      const nextIndex = (roles.indexOf(prev.currentRole) + 1) % roles.length;
      return { ...prev, currentRole: roles[nextIndex] };
    });
    setSelectedBuildingId(null);
    setFocusedCell(null);
  };

  const getAppBackground = () => {
    if (state.pollution > 60) return 'bg-stone-500';
    if (state.pollution > 40) return 'bg-stone-300';
    return 'bg-blue-50';
  };

  const memoizedSidebarLeft = useMemo(() => (
    <SidebarLeft 
      currentRole={state.currentRole} 
      onSelectBuilding={setSelectedBuildingId}
      selectedId={selectedBuildingId}
      gold={state.gold}
    />
  ), [state.currentRole, selectedBuildingId, state.gold]);

  const memoizedSidebarRight = useMemo(() => (
    <SidebarRight 
      tasks={tasks} aiAdvice={aiAdvice} feedbacks={feedbacks}
      currentRole={state.currentRole}
      onSendFeedback={handleSendFeedback}
      onRewardClick={() => { setState(prev => ({ ...prev, gold: prev.gold + 500 })); alert("Government Grant Received!"); }}
    />
  ), [tasks, aiAdvice, feedbacks, state.currentRole]);

  // Handle survey completion: Log if there's a note, then go to Feedback report
  const handleSurveyComplete = (thankYouNote?: string) => {
    if (thankYouNote) {
      setState(prev => ({
        ...prev,
        logs: [...prev.logs, {
          session_id: prev.sessionId,
          timestamp: Math.floor((Date.now() - prev.startTime) / 1000),
          player_id: prev.currentRole,
          event_type: 'discuss',
          discuss_tag: thankYouNote
        }]
      }));
    }
    setView('CHILD_FEEDBACK');
  };

  if (view === 'HOME') {
    return <HomePage onStartGame={handleStartGame} archivedCount={archivedSessions.length} />;
  }

  return (
    <div className={`flex flex-col h-screen w-full transition-colors duration-[3000ms] select-none ${getAppBackground()}`}>
      <TopPanel state={state} onHomeClick={handleEndSession} />

      <div className={`smog-overlay ${state.pollution > 50 ? 'smog-active' : ''}`} style={{ opacity: state.pollution > 50 ? (state.pollution - 50) / 50 : 0 }}></div>

      {showTutorial && <TutorialOverlay onClose={() => setShowTutorial(false)} />}

      {view === 'LOGS' && (
        <LogPage 
          state={state} 
          archivedSessions={archivedSessions}
          onBack={() => setView('GAME')} 
        />
      )}

      {view === 'VOTE' && (
        <VotePage 
          state={state} 
          onBack={() => setView('GAME')} 
          onSubmitVote={handleSubmitVote} 
          onInitiateVote={handleInitiateVote} 
          onCloseVote={handleClearVote}
        />
      )}

      {/* 2-Step Feedback Flow: Survey -> Feedback Report */}
      {view === 'REFLECTION_SURVEY' && (
        <ReflectionSurveyPage 
          currentRole={state.currentRole}
          onComplete={handleSurveyComplete}
          onCancel={() => setView('GAME')}
        />
      )}

      {view === 'CHILD_FEEDBACK' && <ChildFeedbackPage state={state} onBack={() => setView('GAME')} />}

      {view === 'TEACHER_REPORT' && (
        <TeacherReportPage 
          state={state} 
          archivedSessions={archivedSessions}
          onBack={() => setView('GAME')} 
        />
      )}

      <main className="flex flex-1 overflow-hidden">
        {memoizedSidebarLeft}

        <div className="flex-1 flex flex-col relative">
          <GameMap 
            map={state.map}
            isPowered={state.power <= state.powerCapacity}
            onCellClick={handleCellClick}
            selectedBuildingId={selectedBuildingId}
            focusedCell={focusedCell}
          />

          {focusedCell && (
            <BuildingInfoOverlay 
              cell={focusedCell} onClose={() => setFocusedCell(null)} onDemolish={handleDemolish}
            />
          )}

          <div className="absolute top-6 left-6 flex items-center gap-3 bg-white/95 p-3 rounded-2xl shadow-xl border border-gray-100 backdrop-blur-sm">
            <div className="bg-indigo-100 p-2 rounded-xl text-indigo-600">
               <span className="text-xl font-bold">#1</span>
            </div>
            <div>
              <span className="text-[10px] text-gray-400 block font-bold uppercase tracking-widest">
                Current Role: {state.customPlayerId}
              </span>
              <button onClick={switchRole} className="font-bold text-gray-800 hover:text-indigo-600 transition-colors flex items-center gap-1">
                 {state.currentRole} <span className="text-xs">🔄</span>
              </button>
            </div>
          </div>

          {/* 修复关键点：提高 z-index 到 170，确保高于 smog-overlay (z-160) */}
          <div className="h-24 bg-white border-t border-gray-100 flex items-center justify-between px-10 shadow-2xl z-[170] relative">
            <div className="flex gap-4">
              <button onClick={() => setShowTutorial(true)} className="w-12 h-12 flex items-center justify-center bg-gray-100 hover:bg-gray-200 text-gray-400 rounded-2xl font-black text-xl transition-all">?</button>
              <button onClick={() => setSelectedBuildingId(null)} className={`px-8 py-3 rounded-2xl font-bold transition-all ${!selectedBuildingId && !focusedCell ? 'bg-indigo-500 text-white shadow-lg' : 'bg-gray-50 text-gray-400'}`}>Select Mode</button>
              <button onClick={handleRestart} className="px-8 py-3 rounded-2xl font-bold transition-all bg-rose-100 text-rose-500 hover:bg-rose-200 shadow-sm" title="Reset Current Map">Restart</button>
              <button onClick={handleEndSession} className="px-8 py-3 rounded-2xl font-bold transition-all bg-slate-800 text-white hover:bg-slate-900 shadow-sm" title="Save & Return Home">End & Archive</button>
              <button className={`px-8 py-3 rounded-2xl font-bold transition-all ${selectedBuildingId ? 'bg-yellow-400 text-yellow-900 shadow-lg' : 'bg-gray-50 text-gray-400'}`}>Build Mode</button>
            </div>

            <div className="flex gap-8 items-center">
              <button onClick={() => setView('VOTE')} className="group flex flex-col items-center gap-1">
                 <span className="text-2xl">🗳️</span>
                 <span className="text-[10px] font-bold text-gray-400 uppercase">Vote</span>
              </button>
              {/* Updated: Button now navigates to REFLECTION_SURVEY first */}
              <button onClick={() => setView('REFLECTION_SURVEY')} className="group flex flex-col items-center gap-1">
                 <span className="text-2xl">👤📝</span>
                 <span className="text-[10px] font-bold text-gray-400 uppercase">Feedback</span>
              </button>
              <button onClick={() => setView('TEACHER_REPORT')} className="group flex flex-col items-center gap-1">
                 <span className="text-2xl">📊</span>
                 <span className="text-[10px] font-bold text-gray-400 uppercase">Report</span>
              </button>
              <button onClick={() => setView('LOGS')} className="group flex flex-col items-center gap-1">
                 <span className="text-2xl">📝</span>
                 <span className="text-[10px] font-bold text-gray-400 uppercase">Logs</span>
              </button>
            </div>
          </div>
        </div>

        {memoizedSidebarRight}
      </main>
    </div>
  );
};

export default App;
